                for(let i=0;i<9;i++){ let a=(Math.PI*2*i)/9; particles.push(new Particle(this.x + Math.cos(a)*140, this.y + Math.sin(a)*140, '#f3f6ff', 3, 1.2)); }
                this._ultHitMoon = false; this._ultHitAny = false; this._ultHitEnemies = new Set();
