                this.basicCD=0; this.qCD=0; this.eCD=0; this.fCD=0; this.rCD=0;
                this.baseSpd=210; this.speed=210;
                this.revealTimer = 0;
                // Passive shield
                this.specialShield = true;
                this.shieldCD = 0;
                // E ability state
                this.healing = false;
                this.healTimer = 0;
                this.enhancedBasicAttacks = 0; // Water blow attacks after heal
                // F ability state
                this.pulling = false;
                this.pullTimer = 0;
