                        particles.push(new Particle(this.x + (moveX * i/12) + Math.cos(trailAngle)*30, this.y + (moveY * i/12) + Math.sin(trailAngle)*30, '#4169E1', 2, 0.4, Math.cos(trailAngle)*80, Math.sin(trailAngle)*80));
