        // Create mobile control UI with ability buttons
        window.createMobileControls = function() {
            // Check if controls already exist
            if (document.getElementById('mobileControlsContainer')) return;
            
            const isLandscape = window.innerWidth > window.innerHeight;
            const buttonSize = isLandscape ? 45 : 50;
            
            // Create movement joystick
            const joystickContainer = document.createElement('div');
            joystickContainer.id = 'mobileJoystickContainer';
            joystickContainer.style.cssText = `
                position: fixed;
                left: 20px;
                bottom: 20px;
                width: 100px;
                height: 100px;
                background: rgba(0, 0, 0, 0.3);
                border-radius: 50%;
                border: 2px solid #555;
                pointer-events: auto;
                z-index: 100;
                touch-action: none;
            `;
            
            const joystickBase = document.createElement('div');
            joystickBase.style.cssText = `
                position: absolute;
                width: 70px;
                height: 70px;
                background: rgba(255, 255, 255, 0.2);
                border-radius: 50%;
                border: 2px solid #777;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
                pointer-events: none;
            `;
            
            const joystickThumb = document.createElement('div');
            joystickThumb.style.cssText = `
                position: absolute;
                width: 35px;
                height: 35px;
                background: #00bcd4;
                border-radius: 50%;
                border: 2px solid #0097a7;
                top: 50%;
                left: 50%;
                transform: translate(-50%, -50%);
                pointer-events: none;
                transition: transform 0.1s;
                box-shadow: 0 0 10px rgba(0, 188, 212, 0.5);
            `;
            
            joystickContainer.appendChild(joystickBase);
            joystickContainer.appendChild(joystickThumb);
            
            let joystickActive = false;
            let joystickCenter = { x: 0, y: 0 };
            let currentTouchId = null;
            
            joystickContainer.addEventListener('touchstart', (e) => {
                e.preventDefault();
                if (currentTouchId !== null) return;
                const touch = e.touches[0];
                currentTouchId = touch.identifier;
                joystickActive = true;
                const rect = joystickContainer.getBoundingClientRect();
                joystickCenter = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
                updateJoystick(touch.clientX, touch.clientY);
            });
            
            joystickContainer.addEventListener('touchmove', (e) => {
                e.preventDefault();
                if (!joystickActive) return;
                for (let touch of e.touches) {
                    if (touch.identifier === currentTouchId) {
                        updateJoystick(touch.clientX, touch.clientY);
                        break;
                    }
                }
            });
            
            joystickContainer.addEventListener('touchend', (e) => {
                e.preventDefault();
                for (let touch of e.changedTouches) {
                    if (touch.identifier === currentTouchId) {
                        joystickActive = false;
                        currentTouchId = null;
                        resetJoystick();
                        break;
                    }
                }
            });
            
            function updateJoystick(clientX, clientY) {
                const dx = clientX - joystickCenter.x;
                const dy = clientY - joystickCenter.y;
                const distance = Math.sqrt(dx * dx + dy * dy);
                const maxDistance = 30; // Joystick thumb max movement radius
                const clampedDistance = Math.min(distance, maxDistance);
                const angle = Math.atan2(dy, dx);
                
                const thumbX = (clampedDistance / maxDistance) * 17.5 * Math.cos(angle);
                const thumbY = (clampedDistance / maxDistance) * 17.5 * Math.sin(angle);
                
                joystickThumb.style.transform = `translate(-50%, -50%) translate(${thumbX}px, ${thumbY}px)`;
                
                // Update movement keys based on angle
                const deadzone = 10;
                keys.w = keys.s = keys.a = keys.d = false;
                if (clampedDistance > deadzone) {
                    if (angle > -Math.PI/4 && angle < Math.PI/4) keys.d = true; // right
                    else if (angle > Math.PI/4 && angle < 3*Math.PI/4) keys.s = true; // down
                    else if (angle > 3*Math.PI/4 || angle < -3*Math.PI/4) keys.a = true; // left
                    else keys.w = true; // up
                }
            }
            
            function resetJoystick() {
                joystickThumb.style.transform = 'translate(-50%, -50%)';
                keys.w = keys.s = keys.a = keys.d = false;
            }
            
            document.body.appendChild(joystickContainer);
            
            const container = document.createElement('div');
            container.id = 'mobileControlsContainer';
            container.style.cssText = `
                position: fixed;
                ${isLandscape ? 'right: 10px; top: 50%; transform: translateY(-50%); flex-direction: column;' : 'bottom: 20px; right: 20px; flex-direction: row;'}
                display: flex;
                gap: 10px;
                flex-wrap: wrap;
                ${isLandscape ? 'justify-content: center;' : 'justify-content: flex-end;'}
                pointer-events: auto;
                z-index: 100;
                ${isLandscape ? 'max-height: 80vh;' : 'max-width: 300px;'}
            `;
            
            const abilityButtons = [
                { key: 'q', label: 'Q', color: '#ff6b6b' },
                { key: 'e', label: 'E', color: '#4ecdc4' },
                { key: 'f', label: 'F', color: '#ffe66d' },
                { key: 'g', label: 'G', color: '#a78bfa' },
                { key: 'r', label: 'R', color: '#95e1d3' }
            ];
            
            abilityButtons.forEach(btn => {
                const button = document.createElement('button');
                button.style.cssText = `
                    width: ${buttonSize}px;
                    height: ${buttonSize}px;
                    border-radius: 8px;
                    border: 2px solid ${btn.color};
                    background: rgba(0, 0, 0, 0.7);
                    color: ${btn.color};
                    font-weight: bold;
                    font-size: ${buttonSize * 0.36}px;
                    cursor: pointer;
                    touch-action: manipulation;
                    box-shadow: 0 0 10px ${btn.color}4d;
                    transition: all 0.1s;
                `;
                button.innerText = btn.label;
                
                button.addEventListener('touchstart', (e) => {
                    e.preventDefault();
                    keys[btn.key] = true;
                    button.style.transform = 'scale(0.9)';
                    button.style.boxShadow = `0 0 20px ${btn.color}`;
                });
                
                button.addEventListener('touchend', (e) => {
                    e.preventDefault();
                    keys[btn.key] = false;
                    button.style.transform = 'scale(1)';
                    button.style.boxShadow = `0 0 10px ${btn.color}4d`;
                });
                
                // Also support mouse clicks for testing on desktop
                button.addEventListener('mousedown', (e) => {
                    e.preventDefault();
                    keys[btn.key] = true;
                    button.style.transform = 'scale(0.9)';
                    button.style.boxShadow = `0 0 20px ${btn.color}`;
                });
                
                button.addEventListener('mouseup', (e) => {
                    e.preventDefault();
                    keys[btn.key] = false;
                    button.style.transform = 'scale(1)';
                    button.style.boxShadow = `0 0 10px ${btn.color}4d`;
                });
                
                container.appendChild(button);
            });
            
            document.body.appendChild(container);
            
            // Hide controls during hero selection
            const originalDisplay = container.style.display;
            const joystickOriginalDisplay = joystickContainer.style.display;
            window.addEventListener('keydown', (e) => {
                if (document.getElementById('heroSelectScreen').style.display !== 'none') {
                    container.style.display = 'none';
                    joystickContainer.style.display = 'none';
                } else {
                    container.style.display = originalDisplay;
                    joystickContainer.style.display = joystickOriginalDisplay;
                }
            });
            
            // Update controls on orientation change
            window.addEventListener('resize', () => {
                const existing = document.getElementById('mobileControlsContainer');
                const joystickExisting = document.getElementById('mobileJoystickContainer');
                if (existing || joystickExisting) {
                    if (existing) existing.remove();
                    if (joystickExisting) joystickExisting.remove();
                    // Only recreate if game has started (heroSelectScreen is hidden)
                    if (document.getElementById('heroSelectScreen').style.display === 'none') {
                        createMobileControls();
                    }
                }
            });
        };

        // VISIBLE EFFECT CLASSES FOR TWINS
        // Expanding energy wave ring effect
        class EnergyWave {
            constructor(x, y, color, maxRadius = 300, duration = 1.5) {
                this.x = x; this.y = y; this.color = color;
                this.maxRadius = maxRadius; this.duration = duration;
                this.radius = 0; this.del = false; this.age = 0;
            }
            update(dt) {
                this.age += dt;
                if (this.age >= this.duration) { this.del = true; return; }
                this.radius = (this.age / this.duration) * this.maxRadius;
            }
            draw(ctx) {
                let screenX = this.x - camera.x;
                let screenY = this.y - camera.y;
                if (Math.sqrt((screenX)**2 + (screenY)**2) > 2000) return;
                
                let progress = this.age / this.duration;
                let alpha = (1 - progress) * 0.8;
                
                ctx.save();
                try {
                    ctx.strokeStyle = this.color;
                    ctx.globalAlpha = alpha;
                    ctx.lineWidth = 8 - progress * 6;
                    ctx.beginPath();
                    ctx.arc(screenX, screenY, this.radius, 0, Math.PI * 2);
                    ctx.stroke();
                    
                    // Inner glow
                    ctx.strokeStyle = this.color;
                    ctx.globalAlpha = alpha * 0.5;
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.arc(screenX, screenY, this.radius - 10, 0, Math.PI * 2);
                    ctx.stroke();
                } finally {
                    ctx.restore();
                }
            }
        }

        class EnergyCannonBeam {
            constructor(x, y, angle, length, color1 = '#00E5FF', color2 = '#DFFBFF', duration = 0.45) {
                this.x = x; this.y = y; this.angle = angle;
                this.length = length; this.color1 = color1; this.color2 = color2;
                this.duration = duration; this.age = 0; this.del = false;
                this.width = 24;
            }
            update(dt) {
                this.age += dt;
                if (this.age >= this.duration) this.del = true;
            }
            draw(ctx) {
                let screenX = this.x - camera.x;
                let screenY = this.y - camera.y;
                let progress = this.age / this.duration;
                let alpha = (1 - progress) * 0.95;
                let currentLength = this.length * (1 - progress * 0.25);

                ctx.save();
                ctx.translate(screenX, screenY);
                ctx.rotate(this.angle);

                let grad = ctx.createLinearGradient(0, -this.width, currentLength, this.width);
                grad.addColorStop(0, 'rgba(255,255,255,0)');
                grad.addColorStop(0.12, this.color2);
                grad.addColorStop(0.5, this.color1);
                grad.addColorStop(1, 'rgba(0,229,255,0)');

                ctx.globalAlpha = alpha;
                ctx.shadowColor = this.color1;
                ctx.shadowBlur = 30;
                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(0, -this.width * 0.7);
                ctx.lineTo(currentLength, -this.width * 0.35);
                ctx.lineTo(currentLength, this.width * 0.35);
                ctx.lineTo(0, this.width * 0.7);
                ctx.closePath();
                ctx.fill();

                ctx.shadowBlur = 0;
                ctx.fillStyle = '#ffffff';
                ctx.globalAlpha = alpha * 0.8;
                ctx.fillRect(0, -this.width * 0.2, currentLength, this.width * 0.4);

                ctx.globalAlpha = alpha * 0.8;
                ctx.strokeStyle = this.color2;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(0, 0);
                ctx.lineTo(currentLength, 0);
                ctx.stroke();

                ctx.restore();
            }
        }

        // Directional energy beam
        class EnergyBeam {
            constructor(x, y, angle, length, color, duration = 0.5) {
                this.x = x; this.y = y; this.angle = angle;
                this.length = length; this.color = color;
                this.duration = duration; this.age = 0; this.del = false;
                this.width = 25;
            }
            update(dt) {
                this.age += dt;
                if (this.age >= this.duration) this.del = true;
            }
            draw(ctx) {
                let screenX = this.x - camera.x;
                let screenY = this.y - camera.y;
                
                let progress = this.age / this.duration;
                let alpha = (1 - progress) * 0.9;
                let currentLength = this.length * (1 - progress * 0.3);
                
                ctx.save();
                ctx.translate(screenX, screenY);
                ctx.rotate(this.angle);
                
                // Glow gradient
                let grad = ctx.createLinearGradient(0, -this.width/2, currentLength, this.width/2);
                grad.addColorStop(0, this.color);
                grad.addColorStop(0.5, this.color);
                grad.addColorStop(1, 'rgba(255,255,255,0.3)');
                
                ctx.globalAlpha = alpha;
                ctx.fillStyle = grad;
                ctx.beginPath();
                ctx.moveTo(0, -this.width);
                ctx.quadraticCurveTo(currentLength * 0.5, -this.width * 1.5, currentLength, -this.width * 0.5);
                ctx.lineTo(currentLength, this.width * 0.5);
                ctx.quadraticCurveTo(currentLength * 0.5, this.width * 1.5, 0, this.width);
                ctx.closePath();
                ctx.fill();
                
                // Bright core
                ctx.globalAlpha = alpha * 0.6;
                ctx.fillStyle = '#ffffff';
                ctx.fillRect(0, -this.width * 0.3, currentLength, this.width * 0.6);
                
                ctx.restore();
            }
        }

        // Visible energy blast projectile
        class EnergyBlast {
            constructor(x, y, angle, speed, color, size = 30, duration = 2.5) {
                this.x = x; this.y = y; this.angle = angle;
                this.vx = Math.cos(angle) * speed;
                this.vy = Math.sin(angle) * speed;
                this.color = color; this.size = size;
                this.duration = duration; this.age = 0; this.del = false;
                this.trail = [];
            }
            update(dt) {
                this.age += dt;
                if (this.age >= this.duration) { this.del = true; return; }
                
                this.trail.push({x: this.x, y: this.y, age: 0});
                this.trail.forEach(t => t.age += dt);
                this.trail = this.trail.filter(t => t.age < 0.8);
                
                this.x += this.vx * dt;
                this.y += this.vy * dt;
            }
            draw(ctx) {
                let screenX = this.x - camera.x;
                let screenY = this.y - camera.y;
                
                // Draw trail
                this.trail.forEach((t, i) => {
                    let trailScreenX = t.x - camera.x;
                    let trailScreenY = t.y - camera.y;
                    let trailAlpha = (1 - t.age / 0.8) * 0.6;
                    let trailSize = this.size * (1 - t.age / 0.8) * 0.7;
                    
                    ctx.save();
                    ctx.fillStyle = this.color;
                    ctx.globalAlpha = trailAlpha;
                    ctx.beginPath();
                    ctx.arc(trailScreenX, trailScreenY, trailSize, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.restore();
                });
                
                // Main blast
                let progress = this.age / this.duration;
                let alpha = (1 - progress) * 0.9;
                
                ctx.save();
                ctx.globalAlpha = alpha;
                
                // Outer glow
                ctx.fillStyle = this.color;
                ctx.beginPath();
                ctx.arc(screenX, screenY, this.size * 1.5, 0, Math.PI * 2);
                ctx.fill();
                
                // Middle ring
                ctx.fillStyle = this.color;
                ctx.globalAlpha = alpha * 0.7;
                ctx.beginPath();
                ctx.arc(screenX, screenY, this.size, 0, Math.PI * 2);
                ctx.fill();
                
                // Core
                ctx.fillStyle = '#ffffff';
                ctx.globalAlpha = alpha * 0.9;
                ctx.beginPath();
                ctx.arc(screenX, screenY, this.size * 0.5, 0, Math.PI * 2);
                ctx.fill();
                
                ctx.restore();
            }
        }

        // Shockwave ring effect
        class ShockwaveRing {
            constructor(x, y, color, maxRadius = 400, duration = 1.2, width = 12) {
                this.x = x; this.y = y; this.color = color;
                this.maxRadius = maxRadius; this.duration = duration;
                this.radius = 0; this.del = false; this.age = 0; this.width = width;
            }
            update(dt) {
                this.age += dt;
                if (this.age >= this.duration) { this.del = true; return; }
                this.radius = (this.age / this.duration) * this.maxRadius;
            }
            draw(ctx) {
                let screenX = this.x - camera.x;
                let screenY = this.y - camera.y;
                if (Math.sqrt((screenX)**2 + (screenY)**2) > 2500) return;
                
                let progress = this.age / this.duration;
                let alpha = (1 - progress) * 0.95;
                let glow = ctx.createRadialGradient(screenX, screenY, 0, screenX, screenY, this.radius + this.width * 3);
                const solid = this.color.length === 7 ? this.color + 'cc' : this.color;
                glow.addColorStop(0, solid);
                glow.addColorStop(0.2, this.color);
                glow.addColorStop(1, 'rgba(255,255,255,0)');
                
                ctx.save();
                ctx.fillStyle = glow;
                ctx.globalAlpha = alpha * 0.90;
                ctx.beginPath();
                ctx.arc(screenX, screenY, this.radius + this.width * 2.8, 0, Math.PI * 2);
                ctx.fill();
                ctx.strokeStyle = this.color;
                ctx.globalAlpha = alpha;
                ctx.lineWidth = this.width;
                ctx.shadowColor = this.color;
                ctx.shadowBlur = 22;
                ctx.beginPath();
                ctx.arc(screenX, screenY, this.radius, 0, Math.PI * 2);
                ctx.stroke();
                ctx.shadowBlur = 0;
                ctx.globalAlpha = alpha * 0.8;
                ctx.lineWidth = Math.max(2, this.width * 0.38);
                ctx.beginPath();
                ctx.arc(screenX, screenY, this.radius + this.width * 0.7, 0, Math.PI * 2);
                ctx.stroke();
                ctx.beginPath();
                ctx.arc(screenX, screenY, this.radius * 0.66, 0, Math.PI * 2);
                ctx.stroke();
                ctx.restore();
            }
        }

        // Dodge indicator effect
        class DodgeIndicator {
            constructor(x, y, color) {
                this.x = x; this.y = y; this.color = color;
                this.duration = 0.8; this.age = 0; this.del = false;
            }
            update(dt) {
                this.age += dt;
                if (this.age >= this.duration) { this.del = true; return; }
            }
            draw(ctx) {
                let screenX = this.x - camera.x;
                let screenY = this.y - camera.y;
                let progress = this.age / this.duration;
                let alpha = (1 - progress) * 0.8;
                let size = 30 + progress * 20;
                
                ctx.save();
                ctx.globalAlpha = alpha;
                ctx.strokeStyle = this.color;
                ctx.lineWidth = 3;
                ctx.beginPath();
                ctx.arc(screenX, screenY, size, 0, Math.PI * 2);
                ctx.stroke();
                
                // Inner circle
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.arc(screenX, screenY, size * 0.5, 0, Math.PI * 2);
                ctx.stroke();
                ctx.restore();
            }
        }

        // END VISIBLE EFFECTS

        // SECRET HERO - DAYUM
        // THE TWINS - Ken/Matthew with Fusion Matten
        class Twins extends Entity {
            constructor(x, y, p) {
                super(x, y, 22, p ? '#FF1493' : '#FF69B4', 6000);
                this.isPlayer = p || false;
                this.name = p ? 'Player (The Twins)' : 'Enemy Twins';
                this.countsAsFFAHero = true;
                
                // Twin state: 'ken', 'matthew', or 'matten' (fused)
                this.twinState = 'ken';
                this.originalState = 'ken';
                this.fusionBar = 0;
                this.maxFusionBar = 100;
                this.fusionActive = false;
                this.fusionTimer = 0;
                this.maxFusionDuration = 20;
                
                // Cooldowns
                this.basicCD = 0;
                this.qCD = 0;
                this.eCD = 0;
                this.fCD = 0;
                this.gCD = 0;
                this.rCD = 0;
                
                // Knockback tracking
                this.knockbackX = 0;
                this.knockbackY = 0;
                this.knockbackDuration = 0;
                
                this.baseSpd = 260;
                this.speed = this.baseSpd;
                this.angle = 0;
                this.damageReduction = 0;
                
                // Gear
                this.gear = 'speedster';
                this.rageTimer = 0;
                this.speedsterTimer = 0;
                this.bandageTimer = 0;
            }
            
            update(dt) {
                if (this.dead) return;
                this.updateCommon(dt);
                
                // Cooldown decrements
                if (this.basicCD > 0) this.basicCD -= dt;
                if (this.qCD > 0) this.qCD -= dt;
                if (this.eCD > 0) this.eCD -= dt;
                if (this.fCD > 0) this.fCD -= dt;
                if (this.gCD > 0) this.gCD -= dt;
                if (this.rCD > 0) this.rCD -= dt;
                
                // Knockback
                if (this.knockbackDuration > 0) {
                    this.x += this.knockbackX * dt;
                    this.y += this.knockbackY * dt;
                    this.knockbackDuration -= dt;
                }
                
                // Fusion bar charge
                if (!this.fusionActive) {
                    this.fusionBar = Math.min(this.maxFusionBar, this.fusionBar + dt * 2);
                }
                
                // Fusion duration
                if (this.fusionActive) {
                    this.fusionTimer -= dt;
                    if (this.fusionTimer <= 0) {
                        this.quitFusion();
                    }
                }
                
                // Speed boost from tag switch
                if (this.speedsterTimer > 0) {
                    this.speedsterTimer -= dt;
                    if (this.speedsterTimer <= 0) {
                        this.speed = this.fusionActive ? this.baseSpd * 1.3 : this.baseSpd;
                    }
                }
                
                // Gear timers
                if (this.rageTimer > 0) this.rageTimer -= dt;
                if (this.bandageTimer > 0) this.bandageTimer -= dt;
                
                if (this.stunTimer > 0 || this.freezeTimer > 0) { if (this.isPlayer) updateHUD(this); return; }
                if (this.isPlayer) {
                    this.input(dt, this.speed);
                    if (player === this) updateHUD(this);
                } else this.ai(dt, this.speed);
            }
            
            input(dt, spd) {
                let dx = 0, dy = 0;
                if (keys.w) dy--;
                if (keys.s) dy++;
                if (keys.a) dx--;
                if (keys.d) dx++;
                if (dx || dy) {
                    let m = new Vector2(dx, dy).norm().mult(this.getEffectiveSpeed() * dt);
                    this.x += m.x;
                    this.y += m.y;
                }
                this.angle = getMouseAimAngle(this.x, this.y);
                if (mouse.down && this.basicCD <= 0) {
                    this.basicKick();
                    this.basicCD = this.fusionActive ? 0.5 : 0.8;
                }
                if (keys.q && this.qCD <= 0) this.abilityQ();
                if (keys.e && this.eCD <= 0) this.abilityE();
                if (keys.f && this.fCD <= 0) this.abilityF();
                if (keys.g && this.gCD <= 0 && !this.fusionActive) this.abilityG();
                if (keys.r && this.rCD <= 0) this.useGear();
            }
            
            basicKick() {
                const dmg = this.fusionActive ? 140 : 120;
                let color = this.twinState === 'ken' ? '#FF6B6B' : this.twinState === 'matthew' ? '#4ECDC4' : '#FFD700';
                for (let e of entities) {
                    if (e !== this && !e.dead && e.team !== this.team) {
                        let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                        if (d < 120) {
                            e.takeDamage(dmg, this);
                            for (let i = 0; i < 8; i++) {
                                particles.push(new Particle(e.x + (Math.random()-0.5)*60, e.y + (Math.random()-0.5)*60, color, 6, 1.2));
                            }
                            // Add energy burst
                            for (let i = 0; i < 5; i++) {
                                let angle = Math.random() * Math.PI * 2;
                                particles.push(new Particle(e.x + Math.cos(angle) * 40, e.y + Math.sin(angle) * 40, color, 4, 1.0));
                            }
                        }
                    }
                }
            }
            
            abilityQ() {
                if (this.twinState === 'ken' || this.fusionActive) {
                    // KEN Q: Football Shot 1000 damage, injure 10s
                    if (this.fusionActive) {
                        // Matten Q: 300 + 200 true damage, stun 0.5s, injure 12s
                        // Add massive golden energy blast and shockwave
                        visualEffects.push(new EnergyBlast(this.x, this.y, this.angle, 1000, '#FFD700', 50, 3.0));
                        visualEffects.push(new ShockwaveRing(this.x, this.y, '#FFD700', 500, 1.5, 20));
                        for (let e of entities) {
                            if (e !== this && !e.dead && e.team !== this.team) {
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if (d < 500) {
                                    e.takeDamage(300, this);
                                    e.takeDamage(200, this, true);
                                    e.applyStatus('stun', 0.5, this);
                                    e.applyStatus('injure', 12, this);
                                    for (let i = 0; i < 8; i++) {
                                        particles.push(new Particle(e.x + Math.cos(i*Math.PI/4)*50, e.y + Math.sin(i*Math.PI/4)*50, '#FFD700', 7, 1.5));
                                    }
                                }
                            }
                        }
                        // Add golden football trail particles
                        for (let i = 0; i < 15; i++) {
                            let angle = Math.random() * Math.PI * 2;
                            let dist = Math.random() * 100;
                            particles.push(new Particle(this.x + Math.cos(angle) * dist, this.y + Math.sin(angle) * dist, '#FFD700', 6, 2.0));
                        }
                        this.qCD = 2;
                    } else {
                        // Ken Q: Football Shot 1000 damage, injure 10s
                        // Add VISIBLE shockwave effect
                        visualEffects.push(new ShockwaveRing(this.x, this.y, '#FF6B6B', 400, 1.2, 14));
                        // Add VISIBLE energy blast
                        visualEffects.push(new EnergyBlast(this.x, this.y, this.angle, 0, '#FF3333', 40, 0.8));
                        
                        for (let e of entities) {
                            if (e !== this && !e.dead && e.team !== this.team) {
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if (d < 400) {
                                    e.takeDamage(1000, this);
                                    e.applyStatus('injure', 10, this);
                                    for (let i = 0; i < 10; i++) {
                                        particles.push(new Particle(e.x + (Math.random()-0.5)*100, e.y + (Math.random()-0.5)*100, '#FF6B6B', 8, 2));
                                    }
                                }
                            }
                        }
                        // Add visible energy blast effect - expanding shockwave
                        for (let r = 0; r < 400; r += 50) {
                            setTimeout(() => {
                                if (!this.dead) {
                                    for (let i = 0; i < 8; i++) {
                                        let angle = (i / 8) * Math.PI * 2;
                                        let px = this.x + Math.cos(angle) * r;
                                        let py = this.y + Math.sin(angle) * r;
                                        particles.push(new Particle(px, py, '#FF6B6B', 6, 1.5));
                                    }
                                }
                            }, r * 2);
                        }
                        // Add red football trail particles
                        for (let i = 0; i < 12; i++) {
                            let angle = Math.random() * Math.PI * 2;
                            let dist = Math.random() * 80;
                            particles.push(new Particle(this.x + Math.cos(angle) * dist, this.y + Math.sin(angle) * dist, '#FF6B6B', 6, 2.0));
                        }
                        this.qCD = 7;
                    }
                } else {
                    // MATTHEW Q: Dash & Stun 0.5s
                    let dx = Math.cos(this.angle);
                    let dy = Math.sin(this.angle);
                    
                    // Add VISIBLE energy beam showing movement path
                    visualEffects.push(new EnergyBeam(this.x, this.y, this.angle, 200, '#4ECDC4', 0.6));
                    
                    this.x += dx * 200;
                    this.y += dy * 200;
                    for (let e of entities) {
                        if (e !== this && !e.dead && e.team !== this.team) {
                            let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                            if (d < 150) {
                                e.applyStatus('stun', 0.5, this);
                                for (let i = 0; i < 5; i++) {
                                    particles.push(new Particle(e.x, e.y, '#4ECDC4', 4, 0.6));
                                }
                            }
                        }
                    }
                    // Add dash trail particles
                    for (let i = 0; i < 20; i++) {
                        let trailX = this.x - dx * (i * 10);
                        let trailY = this.y - dy * (i * 10);
                        particles.push(new Particle(trailX, trailY, '#4ECDC4', 4, 1.5));
                    }
                    this.qCD = 2;
                }
            }
            
            abilityE() {
                if (this.twinState === 'ken') {
                    // KEN E: Sprint 2x speed 5s, crash stun
                    // Add VISIBLE energy wave effect
                    visualEffects.push(new EnergyWave(this.x, this.y, '#FF6B6B', 200, 0.8));
                    
                    this.speed = this.baseSpd * 2;
                    this.speedsterTimer = 5;
                    setTimeout(() => {
                        if (this.speed === this.baseSpd * 2) this.speed = this.baseSpd;
                    }, 5000);
                    for (let i = 0; i < 6; i++) {
                        particles.push(new Particle(this.x + (Math.random()-0.5)*80, this.y + (Math.random()-0.5)*80, '#FF6B6B', 6, 1.5));
                    }
                    // Add sprint trail particles - energy burst
                    for (let i = 0; i < 25; i++) {
                        let trailAngle = this.angle + (Math.random() - 0.5) * 0.5;
                        let trailDist = i * 8;
                        particles.push(new Particle(this.x - Math.cos(trailAngle) * trailDist, this.y - Math.sin(trailAngle) * trailDist, '#FF6B6B', 4, 2.5));
                    }
                    // Add energy wave behind
                    for (let i = 0; i < 15; i++) {
                        let waveAngle = this.angle + Math.PI + (Math.random() - 0.5) * 0.3;
                        let waveDist = Math.random() * 60;
                        particles.push(new Particle(this.x + Math.cos(waveAngle) * waveDist, this.y + Math.sin(waveAngle) * waveDist, '#FF4444', 5, 1.8));
                    }
                    // Crash detection
                    setTimeout(() => {
                        for (let e of entities) {
                            if (e !== this && !e.dead && e.team !== this.team) {
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if (d < 120) {
                                    e.takeDamage(850, this);
                                    e.applyStatus('stun', 0.5, this);
                                }
                            }
                        }
                    }, 100);
                    this.eCD = 8;
                } else if (this.twinState === 'matthew') {
                    // MATTHEW E: Watch Zone 5s, 350/s, 15% damage reduction
                    // Add VISIBLE zone wave effect and shockwave
                    visualEffects.push(new EnergyWave(this.x, this.y, '#4ECDC4', 200, 1.2));
                    visualEffects.push(new ShockwaveRing(this.x, this.y, '#4ECDC4', 250, 1.0, 12));
                    let zone = {
                        x: this.x,
                        y: this.y,
                        radius: 250,
                        duration: 5,
                        owner: this,
                        update: function(dt) {
                            this.duration -= dt;
                            for (let e of entities) {
                                if (e !== this.owner && !e.dead && e.team !== this.owner.team) {
                                    let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                    if (d < this.radius) {
                                        e.takeDamage(150 * dt, this.owner);
                                    }
                                }
                            }
                        },
                        draw: function(ctx) {
                            ctx.fillStyle = 'rgba(78, 205, 196, 0.2)';
                            ctx.beginPath();
                            ctx.arc(this.x - camera.x, this.y - camera.y, this.radius, 0, Math.PI*2);
                            ctx.fill();
                        }
                    };
                    // Add to world zones if available
                    if (!window.worldZones) window.worldZones = [];
                    window.worldZones.push(zone);
                    this.damageReduction = 0.15;
                    setTimeout(() => {
                        this.damageReduction = 0;
                    }, 5000);
                    // Add zone activation particles
                    for (let i = 0; i < 15; i++) {
                        let angle = (i / 15) * Math.PI * 2;
                        particles.push(new Particle(this.x + Math.cos(angle) * 200, this.y + Math.sin(angle) * 200, '#4ECDC4', 5, 2.0));
                    }
                    // Add energy pulse effects
                    for (let pulse = 0; pulse < 3; pulse++) {
                        setTimeout(() => {
                            if (!this.dead) {
                                for (let i = 0; i < 12; i++) {
                                    let angle = (i / 12) * Math.PI * 2;
                                    let radius = 150 + pulse * 30;
                                    particles.push(new Particle(this.x + Math.cos(angle) * radius, this.y + Math.sin(angle) * radius, '#4ECDC4', 4, 1.5));
                                }
                            }
                        }, pulse * 2000);
                    }
                    this.eCD = 8;
                } else {
                    // MATTEN E: Zone with slowness & football kick
                    // Add VISIBLE golden zone wave
                    visualEffects.push(new EnergyWave(this.x, this.y, '#FFD700', 180, 1.0));
                    
                    let zone = {
                        x: this.x,
                        y: this.y,
                        radius: 250,
                        duration: 5,
                        owner: this,
                        update: function(dt) {
                            this.duration -= dt;
                            for (let e of entities) {
                                if (e !== this.owner && !e.dead && e.team !== this.owner.team) {
                                    let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                    if (d < this.radius) {
                                        e.takeDamage(80 * dt, this.owner);
                                        e.speed = e.baseSpd * 0.5;
                                    }
                                }
                            }
                        },
                        draw: function(ctx) {
                            ctx.fillStyle = 'rgba(255, 215, 0, 0.15)';
                            ctx.beginPath();
                            ctx.arc(this.x - camera.x, this.y - camera.y, this.radius, 0, Math.PI*2);
                            ctx.fill();
                        }
                    };
                    if (!window.worldZones) window.worldZones = [];
                    window.worldZones.push(zone);
                    // Add fusion zone activation particles
                    for (let i = 0; i < 20; i++) {
                        let angle = (i / 20) * Math.PI * 2;
                        particles.push(new Particle(this.x + Math.cos(angle) * 200, this.y + Math.sin(angle) * 200, '#FFD700', 6, 2.5));
                    }
                    // Add golden energy waves
                    for (let wave = 0; wave < 4; wave++) {
                        setTimeout(() => {
                            if (!this.dead) {
                                for (let i = 0; i < 16; i++) {
                                    let angle = (i / 16) * Math.PI * 2;
                                    let radius = 150 + wave * 25;
                                    particles.push(new Particle(this.x + Math.cos(angle) * radius, this.y + Math.sin(angle) * radius, '#FFD700', 5, 2.0));
                                }
                            }
                        }, wave * 1500);
                    }
                    // Then football kick
                    for (let e of entities) {
                        if (e !== this && !e.dead && e.team !== this.team) {
                            let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                            if (d < 400) {
                                e.takeDamage(950, this);
                                for (let i = 0; i < 10; i++) {
                                    particles.push(new Particle(e.x + (Math.random()-0.5)*100, e.y + (Math.random()-0.5)*100, '#FFD700', 7, 2));
                                }
                            }
                        }
                    }
                    this.eCD = 8;
                }
            }
            
            abilityF() {
                if (this.twinState === 'ken') {
                    // KEN F: Explosive Kick 1150 damage, knockback
                    // Add VISIBLE kick beam
                    visualEffects.push(new EnergyBeam(this.x, this.y, this.angle, 200, '#FF6B6B', 0.8));
                    // Add VISIBLE shockwave
                    visualEffects.push(new ShockwaveRing(this.x, this.y, '#FF3333', 350, 1.0, 16));
                    
                    let dx = Math.cos(this.angle);
                    let dy = Math.sin(this.angle);
                    this.knockbackX = dx * 300;
                    this.knockbackY = dy * 300;
                    this.knockbackDuration = 0.5;
                    // Add kick direction particles - energy shockwave
                    for (let i = 0; i < 30; i++) {
                        let particleAngle = this.angle + (Math.random() - 0.5) * 0.8;
                        let particleDist = Math.random() * 150;
                        particles.push(new Particle(this.x + Math.cos(particleAngle) * particleDist, this.y + Math.sin(particleAngle) * particleDist, '#FF6B6B', 5, 2.0));
                    }
                    // Add directional energy blast
                    for (let i = 0; i < 20; i++) {
                        let blastAngle = this.angle + (Math.random() - 0.5) * 0.4;
                        let blastDist = 50 + Math.random() * 100;
                        particles.push(new Particle(this.x + Math.cos(blastAngle) * blastDist, this.y + Math.sin(blastAngle) * blastDist, '#FF3333', 7, 2.2));
                    }
                    setTimeout(() => {
                        for (let e of entities) {
                            if (e !== this && !e.dead && e.team !== this.team) {
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if (d < 200) {
                                    e.takeDamage(1150, this);
                                    e.knockbackX = dx * 400;
                                    e.knockbackY = dy * 400;
                                    e.knockbackDuration = 0.3;
                                    for (let i = 0; i < 12; i++) {
                                        particles.push(new Particle(e.x + (Math.random()-0.5)*120, e.y + (Math.random()-0.5)*120, '#FF6B6B', 8, 1.5));
                                    }
                                }
                            }
                        }
                    }, 500);
                    this.fCD = 10;
                } else if (this.twinState === 'matthew') {
                    // MATTHEW F: Kick 1250 damage, 625 shield
                    // Add visible energy beam and shockwave
                    visualEffects.push(new EnergyBeam(this.x, this.y, this.angle, 300, '#4ECDC4', 1.0));
                    visualEffects.push(new ShockwaveRing(this.x, this.y, '#4ECDC4', 350, 1.2, 16));
                    for (let e of entities) {
                        if (e !== this && !e.dead && e.team !== this.team) {
                            let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                            if (d < 250) {
                                e.takeDamage(1250, this);
                                this.hp = Math.min(this.maxHp, this.hp + 625);
                                for (let i = 0; i < 10; i++) {
                                    particles.push(new Particle(this.x + (Math.random()-0.5)*80, this.y + (Math.random()-0.5)*80, '#4ECDC4', 7, 1.5));
                                }
                                // Add shield gain particles
                                for (let i = 0; i < 15; i++) {
                                    particles.push(new Particle(this.x + (Math.random()-0.5)*60, this.y + (Math.random()-0.5)*60, '#00FF00', 4, 1.0));
                                }
                            }
                        }
                    }
                    this.fCD = 12;
                } else {
                    // MATTEN F: Devastating kick 1150 damage + enhanced basic 1250 damage, 800 shield
                    // Add VISIBLE golden beam
                    visualEffects.push(new EnergyBeam(this.x, this.y, this.angle, 250, '#FFD700', 1.0));
                    // Add VISIBLE massive shockwave
                    visualEffects.push(new ShockwaveRing(this.x, this.y, '#FFD700', 400, 1.3, 18));
                    
                    let dx = Math.cos(this.angle);
                    let dy = Math.sin(this.angle);
                    this.knockbackX = dx * 300;
                    this.knockbackY = dy * 300;
                    this.knockbackDuration = 0.5;
                    // Add massive golden kick particles
                    for (let i = 0; i < 40; i++) {
                        let particleAngle = this.angle + (Math.random() - 0.5) * 1.2;
                        let particleDist = Math.random() * 200;
                        particles.push(new Particle(this.x + Math.cos(particleAngle) * particleDist, this.y + Math.sin(particleAngle) * particleDist, '#FFD700', 6, 2.5));
                    }
                    // Add golden shockwave
                    for (let r = 0; r < 250; r += 40) {
                        setTimeout(() => {
                            if (!this.dead) {
                                for (let i = 0; i < 10; i++) {
                                    let angle = (i / 10) * Math.PI * 2;
                                    let px = this.x + Math.cos(angle) * r;
                                    let py = this.y + Math.sin(angle) * r;
                                    particles.push(new Particle(px, py, '#FFD700', 8, 2.0));
                                }
                            }
                        }, r * 3);
                    }
                    setTimeout(() => {
                        for (let e of entities) {
                            if (e !== this && !e.dead && e.team !== this.team) {
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if (d < 200) {
                                    e.takeDamage(1150, this);
                                    e.knockbackX = dx * 400;
                                    e.knockbackY = dy * 400;
                                    e.knockbackDuration = 0.3;
                                    for (let i = 0; i < 12; i++) {
                                        particles.push(new Particle(e.x + (Math.random()-0.5)*120, e.y + (Math.random()-0.5)*120, '#FFD700', 8, 2));
                                    }
                                }
                            }
                        }
                        // Enhanced basic
                        for (let e of entities) {
                            if (e !== this && !e.dead && e.team !== this.team) {
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if (d < 150) {
                                    e.takeDamage(1250, this);
                                    this.hp = Math.min(this.maxHp, this.hp + 800);
                                }
                            }
                        }
                    }, 500);
                    this.fCD = 12;
                }
            }
            
            abilityG() {
                if (!this.fusionActive && this.fusionBar >= this.maxFusionBar) {
                    // Fusion!
                    this.startFusion();
                } else {
                    // Tag switch
                    if (this.twinState === 'ken') {
                        this.twinState = 'matthew';
                    } else {
                        this.twinState = 'ken';
                    }
                    this.speed = this.baseSpd * 1.5;
                    this.speedsterTimer = 2;
                    this.hp = Math.min(this.maxHp, this.hp + 200);
                    // Charge fusion bar by 20%
                    this.fusionBar = Math.min(this.maxFusionBar, this.fusionBar + this.maxFusionBar * 0.2);
                    // Add tag switch particles
                    for (let i = 0; i < 20; i++) {
                        let angle = (i / 20) * Math.PI * 2;
                        let color = this.twinState === 'ken' ? '#FF6B6B' : '#4ECDC4';
                        particles.push(new Particle(this.x + Math.cos(angle) * 80, this.y + Math.sin(angle) * 80, color, 3, 1.0));
                    }
                    for (let i = 0; i < 5; i++) {
                        particles.push(new Particle(this.x + (Math.random()-0.5)*60, this.y + (Math.random()-0.5)*60, this.twinState === 'ken' ? '#FF6B6B' : '#4ECDC4', 4, 0.6));
                    }
                    this.gCD = 7;
                }
            }
            
            startFusion() {
                this.fusionActive = true;
                this.twinState = 'matten';
                this.fusionTimer = this.maxFusionDuration;
                this.fusionBar = 0;
                this.maxHp = 7500;
                this.hp = Math.min(7500, this.hp + 2500);
                this.speed = this.baseSpd * 1.3;
                this.damageReduction = 0.15;
                this.radius = 25;
                // Immense fusion effect with more particles, bigger size, longer duration
                for (let i = 0; i < 80; i++) {
                    particles.push(new Particle(this.x + (Math.random()-0.5)*150, this.y + (Math.random()-0.5)*150, '#FFD700', 8, 2.5));
                }
                // Additional gold spark particles
                for (let i = 0; i < 40; i++) {
                    particles.push(new Particle(this.x + (Math.random()-0.5)*100, this.y + (Math.random()-0.5)*100, '#FFFFFF', 4, 1.8));
                }
                // Flashy visual effects for Matten's arrival
                visualEffects.push(new EnergyWave(this.x, this.y, '#FFD700', 500, 2.0));
                visualEffects.push(new ShockwaveRing(this.x, this.y, '#FFD700', 600, 1.8, 25));
                for (let i = 0; i < 8; i++) {
                    let angle = (i / 8) * Math.PI * 2;
                    visualEffects.push(new EnergyBeam(this.x, this.y, angle, 300, '#FFD700', 1.5));
                }
                // Screen shake for dramatic effect
                screenShake(15);
                this.gCD = 25;
            }
            
            quitFusion() {
                this.fusionActive = false;
                this.twinState = this.originalState;
                this.maxHp = 6000;
                this.hp = Math.min(6000, this.hp);
                this.radius = 22;
                this.damageReduction = 0;
                this.speed = this.baseSpd;
                for (let i = 0; i < 15; i++) {
                    particles.push(new Particle(this.x + (Math.random()-0.5)*80, this.y + (Math.random()-0.5)*80, this.twinState === 'ken' ? '#FF6B6B' : '#4ECDC4', 7, 1.5));
                }
                this.gCD = 7;
            }
            
            takeDamage(amount, source, isTrue) {
                if (isTrue) {
                    this.hp -= amount;
                } else {
                    let reduction = this.damageReduction || 0;
                    this.hp -= amount * (1 - reduction);
                }
                if (this.hp <= 0) {
                    this.hp = 0;
                    this.die(source);
                }
            }
            
            getEffectiveSpeed() {
                let s = this.speed;
                if (this.speedsterTimer > 0) s *= 1.5;
                if (this.fusionActive) s *= 1.3;
                return s;
            }
            
            getDamageMult() {
                return this.rageTimer > 0 ? 1.15 : 1;
            }
            
            draw(ctx) {
                if (this.dead) return;
                
                let screenX = this.x - camera.x;
                let screenY = this.y - camera.y;
                
                // Color based on state
                let color = this.twinState === 'ken' ? '#FF6B6B' : this.twinState === 'matthew' ? '#4ECDC4' : '#FFD700';
                
                // Energy aura effect - pulsing outer ring
                let auraRadius = this.radius + 8 + Math.sin(Date.now() * 0.01) * 4;
                ctx.save();
                ctx.globalAlpha = 0.4;
                ctx.strokeStyle = color;
                ctx.lineWidth = 3;
                ctx.beginPath();
                ctx.arc(screenX, screenY, auraRadius, 0, Math.PI*2);
                ctx.stroke();
                ctx.restore();
                
                // Inner energy field
                ctx.save();
                ctx.globalAlpha = 0.2;
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.arc(screenX, screenY, this.radius + 5, 0, Math.PI*2);
                ctx.fill();
                ctx.restore();
                
                ctx.fillStyle = color;
                ctx.beginPath();
                ctx.arc(screenX, screenY, this.radius, 0, Math.PI*2);
                ctx.fill();
                
                // Border
                ctx.strokeStyle = this.team === 0 ? '#00ff00' : '#ff0000';
                ctx.lineWidth = 2;
                ctx.stroke();
                
                // Fusion bar indicator
                if (!this.fusionActive && this.fusionBar > 0) {
                    ctx.fillStyle = 'rgba(255, 215, 0, 0.7)';
                    ctx.fillRect(screenX - 30, screenY - this.radius - 15, 60 * (this.fusionBar / this.maxFusionBar), 8);
                    ctx.strokeStyle = '#FFD700';
                    ctx.lineWidth = 1;
                    ctx.strokeRect(screenX - 30, screenY - this.radius - 15, 60, 8);
                }
                
                // Fusion active indicator
                if (this.fusionActive) {
                    ctx.fillStyle = 'rgba(255, 215, 0, 0.3)';
                    ctx.beginPath();
                    ctx.arc(screenX, screenY, this.radius + 10, 0, Math.PI*2);
                    ctx.fill();
                    ctx.strokeStyle = '#FFD700';
                    ctx.lineWidth = 2;
                    ctx.stroke();
                }
                
                // Draw aim pointer line with glow
                ctx.save();
                ctx.shadowColor = '#fff';
                ctx.shadowBlur = 5;
                ctx.beginPath();
                ctx.moveTo(screenX, screenY);
                ctx.lineTo(screenX + Math.cos(this.angle) * (this.radius + 20), screenY + Math.sin(this.angle) * (this.radius + 20));
                ctx.strokeStyle = '#fff';
                ctx.lineWidth = 4;
                ctx.stroke();
                ctx.restore();
            }
            
            ai(dt, spd) {
                let closest = null;
                let closestDist = 9999;
                for (let e of entities) {
                    if (e !== this && !e.dead && e.team !== this.team) {
                        let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                        if (d < closestDist) {
                            closestDist = d;
                            closest = e;
                        }
                    }
                }
                if (closest) {
                    let dx = closest.x - this.x;
                    let dy = closest.y - this.y;
                    let d = Math.sqrt(dx*dx + dy*dy);
                    let m = new Vector2(dx, dy).norm().mult(this.getEffectiveSpeed() * dt);
                    this.x += m.x;
                    this.y += m.y;
                    this.angle = Math.atan2(dy, dx);
                    if (this.basicCD <= 0) { this.basicKick(); this.basicCD = this.fusionActive ? 0.5 : 0.8; }
                    if (Math.random() < 0.05 && this.qCD <= 0) this.abilityQ();
                    if (Math.random() < 0.04 && this.eCD <= 0) this.abilityE();
                    if (Math.random() < 0.03 && this.fCD <= 0) this.abilityF();
                    if (Math.random() < 0.02 && this.fusionBar >= this.maxFusionBar && this.gCD <= 0) this.abilityG();
                    else if (Math.random() < 0.1 && this.gCD <= 0) this.abilityG();
                }
            }
            
            useGear() {
                if (typeof Entity.prototype.useGear === 'function') {
                    return Entity.prototype.useGear.call(this);
                }
            }
        }

        // TRENT - Evader
        // A martial artist who achieved a calm mind to dodge every attack. He was once Li's chaotic student, 
        // whose raw talent clashed with his master's disciplined teachings. Through years of meditation and 
        // rigorous training, Trent mastered the art of "flow" - a state of perfect awareness that allows him 
        // to anticipate and evade attacks with supernatural precision. Now, as a wandering warrior, he seeks 
        // to pass on his wisdom while protecting the innocent from chaos.
        // STATS: Survival 60%, Damage 80%, Agility 100%, Speed 65%, Difficulty 60%
        class Trent extends Entity {
            constructor(x, y, p) {
                super(x, y, 22, p ? '#00008B' : '#191970', 5900);
                this.isPlayer = p;
                this.countsAsFFAHero = true;
                this.name = p ? 'Player (Trent)' : 'Enemy Trent';
                
                // Flow system
                this.flowCharges = 1;
                this.maxFlowCharges = 3;
                this.flowChargeTime = 3; // seconds per charge
                this.flowTimers = [0, 0, 0]; // timers for each charge
                
                // Cooldowns
                this.basicCD = 0;
                this.qCD = 0;
                this.eCD = 0;
                this.fCD = 0;
                this.gCD = 0;
                this.rCD = 0;
                
                // Buffs from E ability
                this.deepBreathActive = false;
                this.deepBreathTimer = 0;
                this.flowChargeTimeBuffed = 2; // during deep breath
                
                this.baseSpd = 290;
                this.speed = this.baseSpd;
                this.angle = 0;
                
                // Gear
                this.gear = 'speedster';
            }
            
            update(dt) {
                if (this.dead) return;
                this.updateCommon(dt);
                
                // Cooldown decrements
                if (this.basicCD > 0) this.basicCD -= dt;
                if (this.qCD > 0) this.qCD -= dt;
                if (this.eCD > 0) this.eCD -= dt;
                if (this.fCD > 0) this.fCD -= dt;
                if (this.gCD > 0) this.gCD -= dt;
                if (this.rCD > 0) this.rCD -= dt;
                
                // Flow charge timers
                for (let i = 0; i < this.maxFlowCharges; i++) {
                    if (this.flowCharges < this.maxFlowCharges && this.flowTimers[i] <= 0) {
                        this.flowTimers[i] = this.deepBreathActive ? this.flowChargeTimeBuffed : this.flowChargeTime;
                    }
                    if (this.flowTimers[i] > 0) {
                        this.flowTimers[i] -= dt;
                        if (this.flowTimers[i] <= 0) {
                            this.flowCharges = Math.min(this.maxFlowCharges, this.flowCharges + 1);
                        }
                    }
                }
                
                // Dash update
                if (this.dashing) {
                    let moveDist = this.dashSpeed * dt;
                    if (this.dashTraveled + moveDist >= this.dashDistance) {
                        moveDist = this.dashDistance - this.dashTraveled;
                        this.dashing = false;
                    }
                    this.x += Math.cos(this.dashDirection) * moveDist;
                    this.y += Math.sin(this.dashDirection) * moveDist;
                    this.dashTraveled += moveDist;
                    // Trail particles
                    particles.push(new Particle(this.x, this.y, '#00008B', 4, 1.0));
                    particles.push(new Particle(this.x + (Math.random()-0.5)*10, this.y + (Math.random()-0.5)*10, '#C0C0C0', 3, 1.2));
                }
                
                // Deep breath buff timer
                if (this.deepBreathActive) {
                    this.deepBreathTimer -= dt;
                    
                    // Additional effects during deep breath (especially first second)
                    if (this.deepBreathTimer > 4) { // First second
                        // Flow state visual effects
                        if (Math.random() < 0.3) {
                            for (let i = 0; i < 3; i++) {
                                let angle = Math.random() * Math.PI * 2;
                                let dist = Math.random() * 60;
                                particles.push(new Particle(this.x + Math.cos(angle)*dist, this.y + Math.sin(angle)*dist, '#C0C0C0', 3, 1.0));
                            }
                        }
                    }
                    
                    if (this.deepBreathTimer <= 0) {
                        this.deepBreathActive = false;
                    }
                }
                
                if (this.stunTimer > 0 || this.freezeTimer > 0) { if (this.isPlayer) updateHUD(this); return; }
                if (this.isPlayer) {
                    this.input(dt, this.speed);
                    if (player === this) updateHUD(this);
                } else {
                    this.ai(dt, this.speed);
                }
            }
            
            input(dt, spd) {
                let dx = 0, dy = 0;
                if (keys.w) dy--;
                if (keys.s) dy++;
                if (keys.a) dx--;
                if (keys.d) dx++;
                if (dx || dy) {
                    let m = new Vector2(dx, dy).norm().mult(this.getEffectiveSpeed() * dt);
                    this.x += m.x;
                    this.y += m.y;
                }
                this.angle = getMouseAimAngle(this.x, this.y);
                if (mouse.down && this.basicCD <= 0) {
                    this.basicPunch();
                    this.basicCD = 0.5;
                }
                if (keys.q && this.qCD <= 0) this.abilityQ();
                if (keys.e && this.eCD <= 0) this.abilityE();
                if (keys.f && this.fCD <= 0) this.abilityF();
                if (keys.g && this.gCD <= 0) this.abilityG();
                if (keys.r && this.rCD <= 0) this.useGear();
            }
            
            basicPunch() {
                for (let e of entities) {
                    if (e !== this && !e.dead && e.team !== this.team) {
                        let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                        if (d < 100) {
                            e.takeDamage(100, this);
                            // Enhanced visible effects
                            for (let i = 0; i < 8; i++) {
                                particles.push(new Particle(e.x + (Math.random()-0.5)*60, e.y + (Math.random()-0.5)*60, '#00008B', 6, 1.5));
                                // Silver punch effect
                                particles.push(new Particle(e.x + (Math.random()-0.5)*40, e.y + (Math.random()-0.5)*40, '#C0C0C0', 4, 2.0));
                            }
                            // Impact flash
                            visualEffects.push(new ImpactFlash(e.x, e.y, '#00008B', 50));
                        }
                    }
                }
            }
            
            abilityQ() {
                // Autonomous Punch - barrage of 100 punches, each 12 damage
                // Visual effect: energy waves around Trent
                visualEffects.push(new EnergyWave(this.x, this.y, '#00008B', 150, 1.0));
                for (let i = 0; i < 100; i++) {
                    setTimeout(() => {
                        if (!this.dead) {
                            let target = null;
                            let minDist = Infinity;
                            for (let e of entities) {
                                if (e !== this && !e.dead && e.team !== this.team) {
                                    let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                    if (d < minDist) {
                                        minDist = d;
                                        target = e;
                                    }
                                }
                            }
                            if (target) {
                                target.takeDamage(10, this);
                                // Enhanced hit effects
                                particles.push(new Particle(target.x + (Math.random()-0.5)*30, target.y + (Math.random()-0.5)*30, '#00008B', 3, 0.8));
                                particles.push(new Particle(target.x + (Math.random()-0.5)*20, target.y + (Math.random()-0.5)*20, '#C0C0C0', 2, 1.2));
                                // Small impact flash
                                if (i % 10 === 0) visualEffects.push(new ImpactFlash(target.x, target.y, '#00008B', 20));
                            }
                        }
                    }, i * 30); // Spread over time
                }
                this.qCD = 3;
            }
            
            abilityE() {
                // Deep Breath - buffs for 5s after 1s breath
                // Energy aura during the 1s breath window
                let breathAura = {
                    x: this.x,
                    y: this.y,
                    duration: 1.0,
                    del: false,
                    update: function(dt) {
                        this.duration -= dt;
                        if (this.duration <= 0) {
                            this.del = true;
                        }
                    },
                    draw: function(ctx) {
                        ctx.strokeStyle = '#C0C0C0';
                        ctx.lineWidth = 2;
                        ctx.globalAlpha = 0.6;
                        ctx.beginPath();
                        ctx.arc(this.x - camera.x, this.y - camera.y, 40, 0, Math.PI * 2);
                        ctx.stroke();
                        ctx.globalAlpha = 1;
                    }
                };
                visualEffects.push(breathAura);
                
                setTimeout(() => {
                    if (!this.dead) {
                        this.deepBreathActive = true;
                        this.deepBreathTimer = 5;
                        
                        // Create silent martial area
                        let zone = {
                            x: this.x,
                            y: this.y,
                            radius: 160,
                            duration: 5,
                            owner: this,
                            update: function(dt) {
                                this.duration -= dt;
                                // Follow owner
                                this.x = this.owner.x;
                                this.y = this.owner.y;
                                for (let e of entities) {
                                    if (e !== this.owner && !e.dead && e.team !== this.owner.team) {
                                        let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                        if (d < this.radius) {
                                            e.speed = e.baseSpd * 0.7; // Slow down
                                        }
                                    }
                                }
                                // Add silver particle effects
                                if (Math.random() < 0.2) {
                                    for (let i = 0; i < 5; i++) {
                                        let angle = Math.random() * Math.PI * 2;
                                        let dist = Math.random() * this.radius;
                                        particles.push(new Particle(this.x + Math.cos(angle)*dist, this.y + Math.sin(angle)*dist, '#C0C0C0', 3, 1.0));
                                    }
                                }
                            },
                            draw: function(ctx) {
                                ctx.fillStyle = 'rgba(192, 192, 192, 0.1)';
                                ctx.beginPath();
                                ctx.arc(this.x - camera.x, this.y - camera.y, this.radius, 0, Math.PI*2);
                                ctx.fill();
                                // Silver border
                                ctx.strokeStyle = '#C0C0C0';
                                ctx.lineWidth = 2;
                                ctx.stroke();
                            }
                        };
                        if (!window.worldZones) window.worldZones = [];
                        window.worldZones.push(zone);
                        
                        // Visual effects
                        for (let i = 0; i < 20; i++) {
                            particles.push(new Particle(this.x + (Math.random()-0.5)*100, this.y + (Math.random()-0.5)*100, '#00008B', 5, 1.5));
                        }
                    }
                }, 1000);
                this.eCD = 9;
            }
            
            abilityF() {
                // Chi Punch - wide shooting projectile
                let projectile = {
                    x: this.x,
                    y: this.y,
                    startX: this.x,
                    startY: this.y,
                    maxDistance: 1000,
                    vx: Math.cos(this.angle) * 600,
                    vy: Math.sin(this.angle) * 600,
                    owner: this,
                    damagedEnemies: [],
                    del: false,
                    update: function(dt) {
                        let oldX = this.x;
                        let oldY = this.y;
                        this.x += this.vx * dt;
                        this.y += this.vy * dt;
                        
                        // Check distance traveled
                        let distanceTraveled = Math.sqrt((this.x - this.startX)**2 + (this.y - this.startY)**2);
                        if (distanceTraveled > this.maxDistance) {
                            this.del = true;
                            return;
                        }
                        
                        // Check for hits along the movement path
                        for (let e of entities) {
                            if (e !== this.owner && !e.dead && e.team !== this.owner.team) {
                                // Check collision with current position
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if (d < 120) {
                                    // Continuous knockback while in contact - apply force directly
                                    e.x += this.vx * dt * 1.5;
                                    e.y += this.vy * dt * 1.5;
                                    
                                    // Damage only once per enemy
                                    if (!this.damagedEnemies.includes(e)) {
                                        e.takeDamage(1000, this.owner);
                                        this.damagedEnemies.push(e);
                                        // Effects on first hit
                                        for (let i = 0; i < 15; i++) {
                                            particles.push(new Particle(e.x + (Math.random()-0.5)*80, e.y + (Math.random()-0.5)*80, '#00008B', 8, 2.0));
                                            particles.push(new Particle(e.x + (Math.random()-0.5)*60, e.y + (Math.random()-0.5)*60, '#C0C0C0', 6, 2.5));
                                        }
                                        visualEffects.push(new ImpactFlash(e.x, e.y, '#00008B', 80));
                                        // Add intimidating shockwave
                                        for (let i = 0; i < 8; i++) {
                                            let angle = (Math.PI * 2 * i) / 8;
                                            particles.push(new Particle(e.x + Math.cos(angle)*50, e.y + Math.sin(angle)*50, '#FF4500', 4, 1.5, Math.cos(angle)*300, Math.sin(angle)*300));
                                        }
                                    }
                                }
                            }
                        }
                        // Remove if out of bounds
                        if (this.x < 0 || this.x > WORLD_SIZE || this.y < 0 || this.y > WORLD_SIZE) {
                            this.del = true;
                        }
                    },
                    draw: function(ctx) {
                        // Intimidating Chi Punch appearance - lighter silver
                        ctx.fillStyle = '#E8E8E8';
                        ctx.beginPath();
                        ctx.arc(this.x - camera.x, this.y - camera.y, 45, 0, Math.PI * 2);
                        ctx.fill();
                        
                        // Energy core - lighter silver
                        ctx.fillStyle = '#F5F5F5';
                        ctx.beginPath();
                        ctx.arc(this.x - camera.x, this.y - camera.y, 25, 0, Math.PI * 2);
                        ctx.fill();
                        
                        // Outer glow effect
                        ctx.strokeStyle = '#FFFFFF';
                        ctx.lineWidth = 4;
                        ctx.globalAlpha = 0.8;
                        ctx.stroke();
                        ctx.globalAlpha = 1;
                        
                        // Pulsing energy waves
                        let pulse = Math.sin(Date.now() * 0.01) * 0.3 + 0.7;
                        ctx.strokeStyle = '#E8E8E8';
                        ctx.lineWidth = 2;
                        ctx.globalAlpha = pulse * 0.5;
                        ctx.beginPath();
                        ctx.arc(this.x - camera.x, this.y - camera.y, 60, 0, Math.PI * 2);
                        ctx.stroke();
                        ctx.globalAlpha = 1;
                    }
                };
                if (!window.projectiles) window.projectiles = [];
                window.projectiles.push(projectile);
                this.fCD = 7;
            }
            
            abilityG() {
                // Instinct Step - dash forward
                this.dashing = true;
                this.dashDistance = 250;
                this.dashSpeed = 1000; // units per second
                this.dashDirection = this.angle;
                this.dashTraveled = 0;
                // Invulnerable during dash
                this.invulnerableTimer = Math.max(this.invulnerableTimer || 0, 0.5);
                // Visual effects
                visualEffects.push(new EnergyWave(this.x, this.y, '#C0C0C0', 100, 0.5));
                for (let i = 0; i < 15; i++) {
                    particles.push(new Particle(this.x + (Math.random()-0.5)*50, this.y + (Math.random()-0.5)*50, '#00008B', 4, 1.0));
                }
                this.gCD = 5;
            }
            
            takeDamage(amount, source, isTrue) {
                // Flow dodge
                if (this.flowCharges > 0 && !isTrue) {
                    this.flowCharges--;
                    // Counter attack if deep breath active
                    if (this.deepBreathActive && source) {
                        for (let i = 0; i < 20; i++) {
                            setTimeout(() => {
                                if (!this.dead && !source.dead) {
                                    source.takeDamage(18, this);
                                    if (i === 19) source.applyStatus('stun', 0.5, this);
                                }
                            }, i * 25);
                        }
                    }
                    // Illusion effect - create afterimages moving away from attack
                    let dodgeAngle = Math.atan2(this.y - source.y, this.x - source.x); // Direction away from attacker
                    for (let i = 0; i < 3; i++) {
                        setTimeout(() => {
                            if (!this.dead) {
                                let distance = 30 + i * 20; // Increasing distance for each afterimage
                                let afterimageX = this.x + Math.cos(dodgeAngle) * distance;
                                let afterimageY = this.y + Math.sin(dodgeAngle) * distance;
                                
                                visualEffects.push({
                                    x: afterimageX,
                                    y: afterimageY,
                                    duration: 0.4,
                                    del: false,
                                    update: function(dt) {
                                        this.duration -= dt;
                                        if (this.duration <= 0) {
                                            this.del = true;
                                        }
                                    },
                                    draw: function(ctx) {
                                        ctx.globalAlpha = this.duration / 0.4 * 0.6;
                                        ctx.fillStyle = '#C0C0C0';
                                        ctx.beginPath();
                                        ctx.arc(this.x - camera.x, this.y - camera.y, 22, 0, Math.PI * 2);
                                        ctx.fill();
                                        ctx.globalAlpha = 1;
                                    }
                                });
                            }
                        }, i * 60);
                    }
                    // Visual dodge effect with silver style
                    for (let i = 0; i < 20; i++) {
                        particles.push(new Particle(this.x + (Math.random()-0.5)*120, this.y + (Math.random()-0.5)*120, '#FFFFFF', 5, 1.2));
                        particles.push(new Particle(this.x + (Math.random()-0.5)*100, this.y + (Math.random()-0.5)*100, '#C0C0C0', 4, 1.8));
                    }
                    // Dodge indicator
                    visualEffects.push(new DodgeIndicator(this.x, this.y, '#C0C0C0'));
                    return; // Dodge successful, no damage
                }
                super.takeDamage(amount, source, isTrue);
            }
            
            ai(dt, spd) {
                // Basic AI logic
                let target = this.findTarget();
                if (target) {
                    let dx = target.x - this.x;
                    let dy = target.y - this.y;
                    this.angle = Math.atan2(dy, dx);
                    let d = Math.sqrt(dx*dx + dy*dy);
                    if (d > 150) {
                        this.x += Math.cos(this.angle) * spd * dt;
                        this.y += Math.sin(this.angle) * spd * dt;
                    }
                    if (this.qCD <= 0) this.abilityQ();
                    if (this.eCD <= 0) this.abilityE();
                    if (this.fCD <= 0) this.abilityF();
                    if (this.gCD <= 0) this.abilityG();
                }
            }
        }

        class Guest extends Entity {
            constructor(x, y, p) {
                super(x, y, 20, p ? '#8B4513' : '#654321', 7200);
                this.isPlayer = p; this.countsAsFFAHero = true;
                this.name = p ? "Player (Guest)" : "Enemy Guest";
                this.basicCD = 0; this.qCD = 0; this.eCD = 0; this.fCD = 0; this.gCD = 0;
                this.baseSpd = 280;
                this.speed = this.baseSpd;
                this.angle = 0;
                
                // Q Block ability
                this.qBlocking = false;
                this.qBlockTimer = 0;
                
                // E War Rush ability
                this.eRushing = false;
                this.eRushTimer = 0;
                this.eRushDir = 0;
                
                // F Last Man ability
                this.fActive = false;
                this.fTimer = 0;
                this.fShockwaveTimer = 0;
                
                // G Parry ability (charge system like Christian)
                this.gCharges = 0; this.maxGCharges = 1; this.gChargeTimer = 0;
                this.gParrying = false;
                this.gParryTimer = 0;
                
                // Undescribable Rage buff from F
                this.rageActive = false;
                this.rageTimer = 0;
                
                // Rush shield tracking
                this.rushShield = 0;
                
                // Gear integration
                this.gear = 'speedster'; this.rCD = 0; this.rageTimer = 0; this.speedsterTimer = 0; this.bandageTimer = 0;
            }
            
            update(dt) {
                if (this.dead) return;
                this.updateCommon(dt);
                if (this.basicCD > 0) this.basicCD -= dt;
                if (this.qCD > 0) this.qCD -= dt;
                if (this.eCD > 0) this.eCD -= dt;
                if (this.fCD > 0) this.fCD -= dt;
                if (this.gCD > 0) this.gCD -= dt;
                if (this.rCD > 0) this.rCD -= dt;
                if (this.rageTimer > 0) this.rageTimer -= dt;
                if (this.speedsterTimer > 0) this.speedsterTimer -= dt;
                if (this.bandageTimer > 0) this.bandageTimer -= dt;
                
                // Q Block window
                if (this.qBlocking) {
                    this.qBlockTimer -= dt;
                    if (this.qBlockTimer <= 0) {
                        this.qBlocking = false;
                        this.speed = this.baseSpd; // Reset speed when block ends
                    }
                }
                
                // E War Rush movement
                if (this.eRushing) {
                    this.eRushTimer -= dt;
                    let rushSpeed = 800;
                    let oldX = this.x;
                    let oldY = this.y;
                    this.x += Math.cos(this.eRushDir) * rushSpeed * dt;
                    this.y += Math.sin(this.eRushDir) * rushSpeed * dt;
                    
                    // Check for enemy collision during rush
                    let hitEnemy = false;
                    for (let e of entities) {
                        if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                            let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                            if (d < 50) { // Collision radius
                                e.takeDamage(900, this); // Damage on hit
                                hitEnemy = true;
                                break;
                            }
                        }
                    }
                    
                    if (hitEnemy || this.eRushTimer <= 0) {
                        this.eRushing = false;
                        this.shield -= this.rushShield;
                        this.rushShield = 0;
                    }
                }
                
                // F Last Man shockwave
                if (this.fActive) {
                    this.fTimer -= dt;
                    this.fShockwaveTimer -= dt;
                    if (this.fShockwaveTimer <= 0) {
                        this.fShockwaveTimer = 0.1;
                        // Create shockwave damage
                        let hitEnemies = [];
                        for (let e of entities) {
                            if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                                let dx = e.x - this.x;
                                let dy = e.y - this.y;
                                let dist = Math.sqrt(dx*dx + dy*dy);
                                if (dist < 300) {
                                    let angle = Math.atan2(dy, dx);
                                    let angleDiff = Math.abs(angle - this.angle);
                                    if (angleDiff > Math.PI) angleDiff = 2 * Math.PI - angleDiff;
                                    if (angleDiff < Math.PI / 3) { // 60 degree cone
                                        e.takeDamage(80, this);
                                        hitEnemies.push(e);
                                    }
                                }
                            }
                        }
                        // Visual effect
                        for (let i = 0; i < 12; i++) {
                            let a = this.angle + (Math.random() - 0.5) * Math.PI / 3;
                            let vel = new Vector2(Math.cos(a), Math.sin(a)).mult(250 + Math.random() * 150);
                            particles.push(new Particle(this.x + Math.cos(this.angle) * 20, this.y + Math.sin(this.angle) * 20, '#FFA500', 4, 0.5, vel.x, vel.y));
                        }
                        // Additional shockwave ring
                        particles.push(new WaveShockwave(this.x, this.y, 300, 0.3, '#FFA500', '#FFD700'));
                    }
                    if (this.fTimer <= 0) {
                        this.fActive = false;
                        this.fShockwaveTimer = 0;
                    }
                }
                
                // G Parry windup
                if (this.gParrying) {
                    this.gParryTimer -= dt;
                    if (this.gParryTimer <= 0) {
                        this.gParrying = false;
                        this.doParry();
                    }
                }
                
                // Rage buff effects
                if (this.rageActive) {
                    this.speed = this.baseSpd * 1.5;
                } else {
                    this.speed = this.baseSpd;
                }
                if (this.rageTimer <= 0 && this.rageActive) {
                    this.rageActive = false;
                }
                
                if (this.stunTimer > 0) { if (this.isPlayer) updateHUD(this); return; }
                let spd = this.getEffectiveSpeed();
                if (this.isPlayer) { this.input(dt, spd); updateHUD(this); } else this.ai(dt, spd);
            }
            
            input(dt, spd) {
                // Cannot move or change direction during War Rush
                if (!this.eRushing) {
                    let dx = 0, dy = 0;
                    if (keys.w) dy--; if (keys.s) dy++; if (keys.a) dx--; if (keys.d) dx++;
                    if (dx || dy) {
                        let m = new Vector2(dx, dy).norm().mult(spd * dt);
                        this.x += m.x; this.y += m.y;
                    }
                    this.angle = getMouseAimAngle(this.x, this.y);
                }
                
                if (mouse.down && this.basicCD <= 0) this.basicAtk();
                if (keys.q && this.qCD <= 0) this.doBlock();
                if (keys.e && this.eCD <= 0) this.doWarRush();
                if (keys.f && this.fCD <= 0) this.doLastMan();
                if (keys.g && this.gCD <= 0 && this.gCharges > 0) this.startParry();
                if (keys.r && this.rCD <= 0) this.useGear();
            }
            
            basicAtk() {
                this.revealTimer = 0.5;
                this.basicCD = 0.4;
                let dmg = 100;
                let hit = false;
                // Rectangular range: 150 length, 80 width
                for (let e of entities) {
                    if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                        let dx = e.x - this.x;
                        let dy = e.y - this.y;
                        let dist = Math.sqrt(dx*dx + dy*dy);
                        let angleToEnemy = Math.atan2(dy, dx);
                        let angleDiff = angleToEnemy - this.angle;
                        while (angleDiff > Math.PI) angleDiff -= 2 * Math.PI;
                        while (angleDiff < -Math.PI) angleDiff += 2 * Math.PI;
                        // Check if within 40 degrees (half-width) and 150 distance
                        if (Math.abs(angleDiff) < Math.PI / 4.5 && dist < 150) {
                            e.takeDamage(dmg, this);
                            hit = true;
                        }
                    }
                }
                if (this.isPlayer) {
                    // Enhanced effects - always visible
                    for (let i = 0; i < 15; i++) {
                        let a = this.angle + (Math.random() - 0.5) * Math.PI / 2;
                        let vel = new Vector2(Math.cos(a), Math.sin(a)).mult(150 + Math.random() * 100);
                        particles.push(new Particle(this.x + Math.cos(this.angle) * 60, this.y + Math.sin(this.angle) * 60, '#8B4513', 3, 0.5, vel.x, vel.y));
                    }
                    // Sound placeholder - add basic_attack.mp3 to sounds folder
                    // let audio = new Audio('sounds/basic_attack.mp3');
                    // audio.volume = 0.6;
                    // audio.play().catch(e => console.log('Sound failed:', e));
                }
            }
            
            doBlock() {
                this.qCD = 7;
                this.qBlocking = true;
                this.qBlockTimer = 1.0;
                this.speed *= 0.5; // 50% slow
                if (this.isPlayer) {
                    addKillMsg("🛡️ Block Active!");
                    // Enhanced effects
                    for (let i = 0; i < 25; i++) {
                        let a = Math.random() * Math.PI * 2;
                        let dist = 30 + Math.random() * 20;
                        particles.push(new Particle(this.x + Math.cos(a) * dist, this.y + Math.sin(a) * dist, '#FFD700', 2, 0.8));
                    }
                    // Sound placeholder - add block.mp3 to sounds folder
                    // let audio = new Audio('sounds/block.mp3');
                    // audio.volume = 0.7;
                    // audio.play().catch(e => console.log('Sound failed:', e));
                }
            }
            
            doWarRush() {
                this.eCD = 4;
                this.eRushing = true;
                this.eRushTimer = 0.5;
                this.eRushDir = this.angle;
                this.rushShield = Math.floor(this.maxHp * 0.5);
                this.shield += this.rushShield;
                if (this.isPlayer) {
                    addKillMsg("⚡ War Rush!");
                    // Enhanced effects
                    for (let i = 0; i < 20; i++) {
                        let a = this.angle + (Math.random() - 0.5) * Math.PI / 2;
                        let vel = new Vector2(Math.cos(a), Math.sin(a)).mult(300 + Math.random() * 200);
                        particles.push(new Particle(this.x, this.y, '#FFD700', 4, 0.6, vel.x, vel.y));
                    }
                    // Sound placeholder - add war_rush.mp3 to sounds folder
                    // let audio = new Audio('sounds/war_rush.mp3');
                    // audio.volume = 0.8;
                    // audio.play().catch(e => console.log('Sound failed:', e));
                }
            }
            
            doLastMan() {
                this.fCD = 20;
                this.fActive = true;
                this.fTimer = 2.0;
                this.fShockwaveTimer = 0.1;
                // Activate Undescribable Rage
                this.rageActive = true;
                this.rageTimer = 5.0;
                if (this.isPlayer) {
                    addKillMsg("👊 Last Man Standing!");
                    // Enhanced effects
                    for (let i = 0; i < 30; i++) {
                        let a = Math.random() * Math.PI * 2;
                        let dist = 50 + Math.random() * 50;
                        particles.push(new Particle(this.x + Math.cos(a) * dist, this.y + Math.sin(a) * dist, '#FFA500', 5, 0.7));
                    }
                    screenShake(8);
                    // Sound placeholder - add last_man.mp3 to sounds folder
                    // let audio = new Audio('sounds/last_man.mp3');
                    // audio.volume = 0.9;
                    // audio.play().catch(e => console.log('Sound failed:', e));
                }
            }
            
            startParry() {
                if (this.gCharges <= 0 || this.gCD > 0) return;
                this.gCharges--;
                if (this.rageActive) {
                    // During rage, skip windup
                    this.doParry();
                } else {
                    this.gParrying = true;
                    this.gParryTimer = 0.5;
                    if (this.isPlayer) {
                        addKillMsg("⚔️ Parry Windup!");
                        // Enhanced effects
                        for (let i = 0; i < 15; i++) {
                            let a = Math.random() * Math.PI * 2;
                            let dist = 25 + Math.random() * 15;
                            particles.push(new Particle(this.x + Math.cos(a) * dist, this.y + Math.sin(a) * dist, '#FFD700', 3, 0.6));
                        }
                        // Sound placeholder - add parry_windup.mp3 to sounds folder
                        // let audio = new Audio('sounds/parry_windup.mp3');
                        // audio.volume = 0.5;
                        // audio.play().catch(e => console.log('Sound failed:', e));
                    }
                }
            }
            
            doParry() {
                let lungeDist = 150;
                let oldX = this.x;
                let oldY = this.y;
                this.x += Math.cos(this.angle) * lungeDist;
                this.y += Math.sin(this.angle) * lungeDist;
                
                let hitEnemy = null;
                for (let e of entities) {
                    if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                        let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                        if (d < 120) {
                            e.takeDamage(1250, this);
                            e.applyStatus('stun', 1.0, this);
                            hitEnemy = e;
                            break;
                        }
                    }
                }
                
                if (hitEnemy) {
                    this.shield += 360;
                    // Enhanced effects
                    for (let i = 0; i < 25; i++) {
                        particles.push(new Particle(hitEnemy.x + (Math.random()-0.5)*80, hitEnemy.y + (Math.random()-0.5)*80, '#FFD700', 5, 0.8));
                    }
                    screenShake(6);
                    if (this.isPlayer) {
                        addKillMsg("⚔️ Parry Success! +360 Shield");
                        // Sound placeholder - add parry_success.mp3 to sounds folder
                        // let audio = new Audio('sounds/parry_success.mp3');
                        // audio.volume = 0.8;
                        // audio.play().catch(e => console.log('Sound failed:', e));
                    }
                } else {
                    // Return to original position if no hit
                    this.x = oldX;
                    this.y = oldY;
                    if (this.isPlayer) {
                        // Sound for miss placeholder - add parry_miss.mp3 to sounds folder
                        // let audio = new Audio('sounds/parry_miss.mp3');
                        // audio.volume = 0.4;
                        // audio.play().catch(e => console.log('Sound failed:', e));
                    }
                }
            }
            
            takeDamage(dmg, src) {
                if (this.qBlocking) {
                    // Successful block - gain parry charge
                    this.gCharges = Math.min(this.maxGCharges, this.gCharges + 1);
                    this.qBlocking = false;
                    this.speed = this.baseSpd; // Reset speed
                    if (this.isPlayer) addKillMsg("🛡️ Block Success! Gained Parry Charge");
                    return; // No damage taken
                }
                super.takeDamage(dmg, src);
            }
            
            getEffectiveSpeed() {
                let s = this.speed;
                if (this.slowTimer > 0) s *= 0.6;
                if (this.speedsterTimer > 0) s *= 1.5;
                return s;
            }
            
            useGear() {
                if (typeof Entity.prototype.useGear === 'function') {
                    return Entity.prototype.useGear.call(this);
                }
            }
            
            ai(dt, spd) {
                if (this.dead) return;
                let target = this.findTarget();
                if (!target) {
                    if (Math.random() < 0.05) this.angle += (Math.random() - 0.5) * 1;
                    this.x += Math.cos(this.angle) * spd * 0.5 * dt;
                    this.y += Math.sin(this.angle) * spd * 0.5 * dt;
                    return;
                }
                
                let dx = target.x - this.x;
                let dy = target.y - this.y;
                let dist = Math.sqrt(dx*dx + dy*dy);
                
                this.angle = Math.atan2(dy, dx);
                
                if (dist > 200) {
                    this.x += Math.cos(this.angle) * spd * dt;
                    this.y += Math.sin(this.angle) * spd * dt;
                }
                
                if (this.qCD <= 0 && Math.random() < 0.1) this.doBlock();
                if (this.eCD <= 0 && dist < 300 && Math.random() < 0.15) this.doWarRush();
                if (this.fCD <= 0 && dist < 250 && Math.random() < 0.05) this.doLastMan();
                if (this.gCharges > 0 && dist < 150 && Math.random() < 0.2) this.startParry();
                if (this.basicCD <= 0 && dist < 400 && Math.random() < 0.3) this.basicAtk();
            }
            
            findTarget() {
                let c = null, md = 9999;
                for (let e of entities) {
                    if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team && e.isVisibleTo(this)) {
                        let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                        if (d < md) { md = d; c = e; }
                    }
                }
                return c;
            }
            
            draw(ctx) {
                super.draw(ctx);
                
                if (this.isPlayer) {
                    // Show current buffs
                    if (this.qBlocking) {
                        ctx.fillStyle = '#FFD700';
                        ctx.font = 'bold 14px Arial';
                        ctx.textAlign = 'center';
                        ctx.fillText('🛡️ BLOCKING', this.x - camera.x, this.y - camera.y - 70);
                    }
                    if (this.rageActive) {
                        ctx.fillStyle = '#FF4500';
                        ctx.font = 'bold 14px Arial';
                        ctx.textAlign = 'center';
                        ctx.fillText('👊 RAGE', this.x - camera.x, this.y - camera.y - 85);
                    }
                    if (this.eRushing) {
                        ctx.fillStyle = '#FFD700';
                        ctx.font = 'bold 14px Arial';
                        ctx.textAlign = 'center';
                        ctx.fillText('⚡ RUSHING', this.x - camera.x, this.y - camera.y - 100);
                    }
                }
                
                // Draw block effect with pulsing
                if (this.qBlocking) {
                    ctx.save();
                    let pulse = Math.sin(Date.now() / 200) * 2 + 2;
                    ctx.strokeStyle = '#FFD700';
                    ctx.lineWidth = 3 + pulse;
                    ctx.beginPath();
                    ctx.arc(this.x - camera.x, this.y - camera.y, this.radius + 10, 0, Math.PI * 2);
                    ctx.stroke();
                    // Inner glow
                    ctx.strokeStyle = 'rgba(255, 215, 0, 0.5)';
                    ctx.lineWidth = 1;
                    ctx.beginPath();
                    ctx.arc(this.x - camera.x, this.y - camera.y, this.radius + 5, 0, Math.PI * 2);
                    ctx.stroke();
                    ctx.restore();
                }
                
                // Draw rage effect with enhanced visuals
                if (this.rageActive) {
                    ctx.save();
                    ctx.strokeStyle = '#FF4500';
                    ctx.lineWidth = 3;
                    ctx.setLineDash([5, 5]);
                    ctx.beginPath();
                    ctx.arc(this.x - camera.x, this.y - camera.y, this.radius + 15, 0, Math.PI * 2);
                    ctx.stroke();
                    // Additional inner ring
                    ctx.strokeStyle = '#FFA500';
                    ctx.lineWidth = 2;
                    ctx.setLineDash([]);
                    ctx.beginPath();
                    ctx.arc(this.x - camera.x, this.y - camera.y, this.radius + 20, 0, Math.PI * 2);
                    ctx.stroke();
                    ctx.restore();
                }
                
                // Draw rush effect
                if (this.eRushing) {
                    ctx.save();
                    ctx.strokeStyle = '#FFD700';
                    ctx.lineWidth = 4;
                    ctx.beginPath();
                    ctx.arc(this.x - camera.x, this.y - camera.y, this.radius + 12, 0, Math.PI * 2);
                    ctx.stroke();
                    // Trail particles during rush
                    for (let i = 0; i < 3; i++) {
                        let trailX = this.x - Math.cos(this.eRushDir) * (i + 1) * 20;
                        let trailY = this.y - Math.sin(this.eRushDir) * (i + 1) * 20;
                        particles.push(new Particle(trailX, trailY, '#FFD700', 2, 0.3));
                    }
                    ctx.restore();
                }
                
                // Draw parry windup with enhanced effect
                if (this.gParrying) {
                    ctx.save();
                    ctx.fillStyle = 'rgba(255, 215, 0, 0.4)';
                    ctx.beginPath();
                    ctx.arc(this.x - camera.x, this.y - camera.y, this.radius + 20, 0, Math.PI * 2 * (0.5 - this.gParryTimer) / 0.5);
                    ctx.fill();
                    // Outer ring
                    ctx.strokeStyle = '#FFD700';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.arc(this.x - camera.x, this.y - camera.y, this.radius + 25, 0, Math.PI * 2);
                    ctx.stroke();
                    ctx.restore();
                }
                
                // Draw shockwave active indicator
                if (this.fActive) {
                    ctx.save();
                    ctx.strokeStyle = '#FFA500';
                    ctx.lineWidth = 2;
                    ctx.setLineDash([3, 3]);
                    ctx.beginPath();
                    ctx.arc(this.x - camera.x, this.y - camera.y, 300, 0, Math.PI * 2);
                    ctx.stroke();
                    ctx.restore();
                }
            }
        }

        class Jimeka extends Entity {
            constructor(x, y, p) {
                super(x, y, 25, p ? '#FF1493' : '#8B008B', 5600);
                this.isPlayer = p; this.countsAsFFAHero = true;
                this.name = p ? "Player (Jimeka)" : "Enemy Jimeka";
                this.basicCD = 0; this.qCD = 0; this.eCD = 0; this.fCD = 0; this.gCD = 0;
                this.baseSpd = 250;
                this.speed = this.baseSpd;
                this.angle = 0;
                
                // F ability variants
                this.fVariants = [
                    { emoji: '💥', name: 'Big Bang', effect: 'bigBang' },
                    { emoji: '🛡️', name: 'Jester\'s Shield', effect: 'shield' },
                    { emoji: '⚡', name: 'Lightning Rod', effect: 'lightning' },
                    { emoji: '💨', name: 'Speed Circus', effect: 'speed' },
                    { emoji: '🧊', name: 'Freeze Frame', effect: 'freeze' },
                    { emoji: '🔥', name: 'Fireworks', effect: 'fireworks' },
                    { emoji: '💀', name: 'Punchline', effect: 'execute' },
                    { emoji: '💚', name: 'Healing Joke', effect: 'heal' },
                    { emoji: '🔄', name: 'Misfortune', effect: 'swap' },
                    { emoji: '👥', name: 'Clone Prank', effect: 'clones' }
                ];
                this.currentFVariant = this.fVariants[Math.floor(Math.random() * this.fVariants.length)];
                
                // Banana peel trap
                this.bananaPeels = [];
                this.dashDist = 0;
                
                // Gear integration
                this.gear = 'speedster'; this.rCD = 0; this.rageTimer = 0; this.speedsterTimer = 0; this.bandageTimer = 0;
            }
            
            update(dt) {
                if (this.dead) return;
                this.updateCommon(dt);
                if (this.basicCD > 0) this.basicCD -= dt;
                if (this.qCD > 0) this.qCD -= dt;
                if (this.eCD > 0) this.eCD -= dt;
                if (this.fCD > 0) this.fCD -= dt;
                if (this.gCD > 0) this.gCD -= dt;
                if (this.rCD > 0) this.rCD -= dt;
                if (this.rageTimer > 0) this.rageTimer -= dt;
                if (this.speedsterTimer > 0) this.speedsterTimer -= dt;
                if (this.bandageTimer > 0) this.bandageTimer -= dt;
 if (this.dashDist > 0) {
                    let move = Math.min(600 * dt, this.dashDist);
                    this.x += Math.cos(this.angle) * move;
                    this.y += Math.sin(this.angle) * move;
                    this.dashDist -= move;
                    // damage enemies once when touched during dash
                    for (let e of entities) {
                        if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                            let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                            if (d < this.radius + 5 && !this.gDashDamaged.has(e)) {
                                e.takeDamage(250, this);
                                this.gDashDamaged.add(e);
                            }
                        }
                    }
                    // Particles during dash
                    particles.push(new Particle(
                        this.x, this.y, '#FFD700', 3, 0.5,
                        Math.cos(this.angle + Math.PI) * 200,
                        Math.sin(this.angle + Math.PI) * 200
                    ));
                }
                
                // Update banana peels
                for (let i = this.bananaPeels.length - 1; i >= 0; i--) {
                    let peel = this.bananaPeels[i];
                    peel.timer -= dt;
                    if (peel.timer <= 0) {
                        this.bananaPeels.splice(i, 1);
                        continue;
                    }
                    // Check for enemies slipping
                    for (let e of entities) {
                        if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                            let d = Math.sqrt((e.x - peel.x)**2 + (e.y - peel.y)**2);
                            if (d < 80 && !peel.triggered) {
                                e.stunTimer = Math.max(e.stunTimer, 0.5);
                                e.takeDamage(800, this);
                                peel.triggered = true;
                                // Visual effect
                                for (let j = 0; j < 10; j++) {
                                    particles.push(new Particle(peel.x, peel.y, '#FFFF00', 2, 0.5));
                                }
                            }
                        }
                    }
                }
                
                if (this.stunTimer > 0) { if (this.isPlayer) updateHUD(this); return; }
                let spd = this.getEffectiveSpeed();
                if (this.isPlayer) { this.input(dt, spd); updateHUD(this); } else this.ai(dt, spd);
            }
            
            input(dt, spd) {
                let dx = 0, dy = 0;
                if (keys.w) dy--; if (keys.s) dy++; if (keys.a) dx--; if (keys.d) dx++;
                if (dx || dy) {
                    let m = new Vector2(dx, dy).norm().mult(spd * dt);
                    this.x += m.x; this.y += m.y;
                }
                this.angle = getMouseAimAngle(this.x, this.y);
                
                if (mouse.down && this.basicCD <= 0) this.basicAtk();
                if (keys.q && this.qCD <= 0) this.doJestersToss();
                if (keys.e && this.eCD <= 0) this.doPrankstersPlay();
                if (keys.f && this.fCD <= 0) this.doGuess();
                if (keys.g && this.gCD <= 0) this.doReroll();
                if (keys.r && this.rCD <= 0) this.useGear();
            }
            
            basicAtk() {
                this.revealTimer = 0.5;
                this.basicCD = 0.5;
                let dmg = 150;
                // Create sharp dart projectile with proper constructor: (owner, x, y, angle, speed, damage, range, color, size)
                let proj = new Projectile(this, this.x + Math.cos(this.angle) * 20, this.y + Math.sin(this.angle) * 20, this.angle, 800, dmg, 600, '#FF1493', 6);
                proj.trail = true; // Add trailing particles
                proj.dartProjectile = true; // Mark as dart for custom drawing
                entities.push(proj);
                
                // Enhanced visual effect: Pink starburst with trail
                for (let i = 0; i < 12; i++) {
                    let a = this.angle + (i - 6) * Math.PI / 36;
                    let vel = new Vector2(Math.cos(a), Math.sin(a)).mult(300 + Math.random() * 150);
                    particles.push(new Particle(this.x + Math.cos(this.angle) * 25, this.y + Math.sin(this.angle) * 25, '#FFB6C1', 3, 0.6, vel.x, vel.y));
                }
                if (this.isPlayer) screenShake(2);
            }
            
            doJestersToss() {
                this.qCD = 4;
                if (this.isPlayer) {
                    addKillMsg("🎪 Jester's Toss! (10 darts)");
                    screenShake(8);
                }
                
                // Launch 10 projectiles in spread pattern with circus colors
                for (let i = 0; i < 10; i++) {
                    let spreadAngle = this.angle + (i - 4.5) * Math.PI / 36;
                    // Proper Projectile: (owner, x, y, angle, speed, damage, range, color, size)
                    let proj = new Projectile(this, this.x + Math.cos(spreadAngle) * 30, this.y + Math.sin(spreadAngle) * 30, spreadAngle, 850, 200, 650, '#FF1493', 7);
                    proj.trail = true;
                    proj.dartProjectile = true;
                    entities.push(proj);
                }
                
                // Enhanced visual: Massive circus explosion burst
                let colors = ['#FF1493', '#FFD700', '#00BFFF', '#32CD32', '#FF4500'];
                for (let i = 0; i < 40; i++) {
                    let angle = Math.random() * Math.PI * 2;
                    let speed = Math.random() * 400 + 150;
                    let color = colors[Math.floor(Math.random() * colors.length)];
                    particles.push(new Particle(this.x, this.y, color, 4, 1.2, Math.cos(angle) * speed, Math.sin(angle) * speed));
                }
            }
            
            doPrankstersPlay() {
                this.eCD = 8;
                // Apply confusion (slowness) to nearby enemies
                for (let e of entities) {
                    if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                        let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                        if (d < 300) {
                            e.slowTimer = Math.max(e.slowTimer, 2.0);
                            e.slowMultiplier = 0.4;
                        }
                    }
                }
                
                // Place banana peel trap
                this.bananaPeels.push({
                    x: this.x + Math.cos(this.angle) * 120,
                    y: this.y + Math.sin(this.angle) * 120,
                    timer: 4.0,
                    triggered: false
                });
                

                
                if (this.isPlayer) {
                    addKillMsg("🤡 Prankster's Play! (Slow + Trap)");
                    screenShake(6);
                }
                
                // Enhanced visual: Chaotic clown party with confetti burst
                let partyColors = ['#FF1493', '#FFD700', '#00BFFF', '#32CD32', '#FF69B4', '#FF4500', '#9932CC'];
                for (let i = 0; i < 35; i++) {
                    let angle = Math.random() * Math.PI * 2;
                    let speed = Math.random() * 350 + 100;
                    let color = partyColors[Math.floor(Math.random() * partyColors.length)];
                    let dist = Math.random() * 80;
                    particles.push(new Particle(
                        this.x + Math.cos(angle) * dist, 
                        this.y + Math.sin(angle) * dist, 
                        color, 3, 1.4, 
                        Math.cos(angle) * speed, 
                        Math.sin(angle) * speed
                    ));
                }
            }
            
            doGuess() {
                this.fCD = 10;
                let variant = this.currentFVariant;
                if (this.isPlayer) {
                    addKillMsg(`${variant.emoji} ${variant.name}!`);
                }
                
                // Execute the effect
                switch (variant.effect) {
                    case 'bigBang':
                        // Big Bang: 1000 AoE damage, slow 1.5s in 400 radius
                        for (let e of entities) {
                            if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if (d < 400) {
                                    e.takeDamage(1000, this);
                                    e.slowTimer = Math.max(e.slowTimer, 1.5);
                                }
                            }
                        }
                        if (this.isPlayer) addKillMsg('💥 BIG BANG!');
                        screenShake(12);
                        
                        // Custom explosion effects: shockwaves and radial beams
                        try {
                            effectsAdd(new WaveShockwave(this.x, this.y, 400, 1.2, '#FF4500', '#FFD700'));
                            for (let i = 0; i < 8; i++) {
                                let angle = (Math.PI * 2 * i) / 8;
                                effectsAdd(new RadialBeam(this.x, this.y, angle, 400, Math.PI / 4, 1.0, '#FF4500'));
                                effectsAdd(new ImpactFlash(this.x, this.y, angle, 400, 0.8, '#FFD700'));
                            }
                            effectsAdd(new AuraRing(this.x, this.y, 200, 1.5, '#FF6600', -8));
                        } catch(ex) {
                            console.warn('Big Bang effects failed', ex);
                        }
                        
                        // Enhanced particles
                        for (let i = 0; i < 40; i++) {
                            let angle = Math.random() * Math.PI * 2;
                            let speed = Math.random() * 450 + 200;
                            particles.push(new Particle(this.x, this.y, '#FF4500', 7, 1.8, Math.cos(angle) * speed, Math.sin(angle) * speed));
                        }
                        break;
                    case 'shield':
                        // Jester's Shield: 500 shield to all allies +500 extra to self
                        for (let e of entities) {
                            if (!e.dead && e instanceof Entity && e.team === this.team) {
                                e.shield += 500;
                                if (e === this) e.shield += 500; // Extra for self
                            }
                        }
                        if (this.isPlayer) addKillMsg('🛡️ SHIELD UP!');
                        screenShake(5);
                        
                        // Custom shield effects: protective aura and beams
                        try {
                            effectsAdd(new AuraRing(this.x, this.y, 80, 3.0, '#00FF00', 6));
                            for (let i = 0; i < 12; i++) {
                                let angle = (Math.PI * 2 * i) / 12;
                                effectsAdd(new RadialBeam(this.x, this.y, angle, 100, Math.PI / 6, 3.0, '#90EE90'));
                            }
                            effectsAdd(new EntityAura(this, this.radius + 30, 3.0, '#00FF00', '#90EE90', 4));
                        } catch(ex) {
                            console.warn('Shield effects failed', ex);
                        }
                        
                        // Enhanced shield particles
                        for (let i = 0; i < 25; i++) {
                            let angle = Math.random() * Math.PI * 2;
                            particles.push(new Particle(this.x, this.y, '#00FF00', 4, 1.2, Math.cos(angle) * 150, Math.sin(angle) * 150));
                        }
                        break;
                    case 'lightning':
                        // Lightning Rod: 4 directional rods, each deals 300 damage in aiming direction with 60° width, 500 range
                        let lightningWidth = Math.PI / 3; // 60 degrees
                        for (let rod = 0; rod < 4; rod++) {
                            let rodAngle = this.angle + (Math.PI * 2 * rod) / 4;
                            for (let e of entities) {
                                if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                                    let dx = e.x - this.x;
                                    let dy = e.y - this.y;
                                    let dist = Math.sqrt(dx*dx + dy*dy);
                                    if (dist < 500 && dist > 0) {
                                        let enemyAngle = Math.atan2(dy, dx);
                                        let angleDiff = Math.abs(enemyAngle - rodAngle);
                                        if (angleDiff > Math.PI) angleDiff = 2 * Math.PI - angleDiff;
                                        if (angleDiff < lightningWidth / 2) {
                                            e.takeDamage(1200, this);
                                        }
                                    }
                                }
                            }
                        }
                        if (this.isPlayer) addKillMsg('⚡ LIGHTNING STRIKE!');
                        screenShake(10);
                        
                        // Custom lightning effects: directional beams instead of radial burst
                        try {
                            for (let bolt = 0; bolt < 4; bolt++) {
                                let boltAngle = this.angle + (Math.PI * 2 * bolt) / 4;
                                // Lightning beam effect
                                effectsAdd(new RadialBeam(this.x, this.y, boltAngle, 500, Math.PI / 3, 0.8, '#00FFFF'));
                                // Impact flash at end of beam
                                effectsAdd(new ImpactFlash(this.x, this.y, boltAngle, 500, 0.6, '#FFFFFF'));
                                // Sword trail for lightning trail effect
                                effectsAdd(new SwordTrail(this.x, this.y, boltAngle, 500, 0.7, '#87CEEB'));
                            }
                            
                            // Electric field particles along the beams
                            for (let bolt = 0; bolt < 4; bolt++) {
                                let boltAngle = this.angle + (Math.PI * 2 * bolt) / 4;
                                for (let i = 0; i < 20; i++) {
                                    let progress = i / 20;
                                    let dist = progress * 500;
                                    let spread = (Math.random() - 0.5) * 50 * progress;
                                    let particleAngle = boltAngle + spread / dist;
                                    let px = this.x + Math.cos(particleAngle) * dist;
                                    let py = this.y + Math.sin(particleAngle) * dist;
                                    particles.push(new Particle(px, py, '#FFFF00', 3, 0.8 + Math.random() * 0.4));
                                }
                            }
                        } catch(ex) {
                            console.warn('Lightning effects failed', ex);
                            // Fallback to simple particles
                            for (let bolt = 0; bolt < 4; bolt++) {
                                let boltAngle = (Math.PI * 2 * bolt) / 4;
                                for (let i = 0; i < 30; i++) {
                                    let angle = boltAngle + (Math.random() - 0.5) * 0.5;
                                    let speed = Math.random() * 500 + 300;
                                    particles.push(new Particle(
                                        this.x, this.y, 
                                        i % 2 === 0 ? '#FFFF00' : '#87CEEB', 5, 1.0,
                                        Math.cos(angle) * speed,
                                        Math.sin(angle) * speed
                                    ));
                                }
                            }
                        }
                        break;
                    case 'speed':
                        // Speed Circus: 3x speed to all allies for 5s
                        for (let e of entities) {
                            if (!e.dead && e instanceof Entity && e.team === this.team) {
                                e.speed *= 3;
                                e.speedBoostTimer = 5.0;
                                setTimeout(() => { if (!e.dead) e.speed /= 3; }, 5000);
                            }
                        }
                        if (this.isPlayer) addKillMsg('💨 SPEED CIRCUS!');
                        screenShake(7);
                        
                        // Custom speed effects: energy aura and trails
                        try {
                            effectsAdd(new AuraRing(this.x, this.y, 70, 5.0, '#00BFFF', 10));
                            for (let i = 0; i < 8; i++) {
                                let angle = (Math.PI * 2 * i) / 8;
                                effectsAdd(new SwordTrail(this.x, this.y, angle, 120, 5.0, '#87CEEB'));
                            }
                        } catch(ex) {
                            console.warn('Speed effects failed', ex);
                        }
                        
                        // Enhanced speed particles
                        for (let i = 0; i < 25; i++) {
                            let angle = Math.random() * Math.PI * 2;
                            particles.push(new Particle(this.x, this.y, '#00BFFF', 4, 1.4, Math.cos(angle) * 400, Math.sin(angle) * 400));
                        }
                        break;
                    case 'freeze':
                        // Freeze Frame: Freeze all enemies for 2s in 350 radius
                        for (let e of entities) {
                            if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if (d < 350) {
                                    e.stunTimer = Math.max(e.stunTimer, 2.0);
                                }
                            }
                        }
                        if (this.isPlayer) addKillMsg('🧊 FREEZE FRAME!');
                        screenShake(8);
                        
                        // Custom freeze effects: ice shockwave and aura
                        try {
                            effectsAdd(new WaveShockwave(this.x, this.y, 350, 1.0, '#87CEEB', '#B0E0E6'));
                            effectsAdd(new AuraRing(this.x, this.y, 120, 2.0, '#87CEEB', -4));
                            for (let i = 0; i < 6; i++) {
                                let angle = (Math.PI * 2 * i) / 6;
                                effectsAdd(new RadialBeam(this.x, this.y, angle, 350, Math.PI / 3, 1.5, '#B0E0E6'));
                            }
                        } catch(ex) {
                            console.warn('Freeze effects failed', ex);
                        }
                        
                        // Enhanced ice particles
                        for (let i = 0; i < 30; i++) {
                            let angle = Math.random() * Math.PI * 2;
                            particles.push(new Particle(this.x, this.y, '#87CEEB', 5, 1.5, Math.cos(angle) * 350, Math.sin(angle) * 350));
                        }
                        break;
                    case 'fireworks':
                        // Fireworks: 10x150 damage to random targets in 250 radius
                        let targets = [];
                        for (let e of entities) {
                            if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if (d < 250) targets.push(e);
                            }
                        }
                        for (let i = 0; i < 10 && targets.length > 0; i++) {
                            let target = targets[Math.floor(Math.random() * targets.length)];
                            target.takeDamage(150, this);
                        }
                        if (this.isPlayer) addKillMsg('🔥 FIREWORKS EXTRAVAGANZA!');
                        screenShake(9);
                        
                        // Custom fireworks effects: multiple impact flashes and beams
                        try {
                            let fireworkColors = ['#FF6347', '#FFD700', '#32CD32', '#00BFFF', '#FF1493', '#FF4500', '#9932CC'];
                            for (let burst = 0; burst < 8; burst++) {
                                let burstAngle = (Math.PI * 2 * burst) / 8;
                                effectsAdd(new ImpactFlash(this.x, this.y, burstAngle, 250, 1.0, fireworkColors[burst % fireworkColors.length]));
                                effectsAdd(new RadialBeam(this.x, this.y, burstAngle, 250, Math.PI / 4, 1.2, fireworkColors[burst % fireworkColors.length]));
                            }
                        } catch(ex) {
                            console.warn('Fireworks effects failed', ex);
                        }
                        
                        // Enhanced firework particles
                        let fireworkColors = ['#FF6347', '#FFD700', '#32CD32', '#00BFFF', '#FF1493', '#FF4500', '#9932CC'];
                        for (let burst = 0; burst < 8; burst++) {
                            let burstAngle = (Math.PI * 2 * burst) / 8;
                            for (let i = 0; i < 10; i++) {
                                let angle = burstAngle + (Math.random() - 0.5) * 0.8;
                                let speed = Math.random() * 400 + 200;
                                let color = fireworkColors[Math.floor(Math.random() * fireworkColors.length)];
                                particles.push(new Particle(this.x, this.y, color, 5, 1.3, Math.cos(angle) * speed, Math.sin(angle) * speed));
                            }
                        }
                        break;
                    case 'execute':
                        // Punchline: Deal 500 true damage to all enemies in 300 range, execute if below 15%
                        let executedCount = 0;
                        for (let e of entities) {
                            if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if (d < 300) {
                                    e.takeDamage(500, this, true); // True damage
                                    if (e.hp / e.maxHp <= 0.15) {
                                        e.takeDamage(e.hp + 1000, this); // Execute
                                        executedCount++;
                                    }
                                }
                            }
                        }
                        if (this.isPlayer) addKillMsg(`💀 PUNCHLINE!${executedCount > 0 ? ' (EXECUTED!)' : ''}`);
                        screenShake(11);
                        
                        // Custom execute effects: dark shockwave and aura
                        try {
                            effectsAdd(new WaveShockwave(this.x, this.y, 300, 1.5, '#8B0000', '#000000'));
                            effectsAdd(new AuraRing(this.x, this.y, 150, 2.0, '#FF0000', -6));
                            for (let i = 0; i < 8; i++) {
                                let angle = (Math.PI * 2 * i) / 8;
                                effectsAdd(new RadialBeam(this.x, this.y, angle, 300, Math.PI / 4, 1.8, '#8B0000'));
                            }
                        } catch(ex) {
                            console.warn('Execute effects failed', ex);
                        }
                        
                        // Enhanced dark particles
                        for (let i = 0; i < 35; i++) {
                            let angle = Math.random() * Math.PI * 2;
                            particles.push(new Particle(this.x, this.y, Math.random() < 0.5 ? '#8B0000' : '#000000', 6, 1.6, Math.cos(angle) * 450, Math.sin(angle) * 450));
                        }
                        break;
                    case 'heal':
                        // Healing Joke: 400 heal to all allies +400 extra to self
                        for (let e of entities) {
                            if (!e.dead && e instanceof Entity && e.team === this.team) {
                                e.hp = Math.min(e.maxHp, e.hp + 400);
                                if (e === this) e.hp = Math.min(e.maxHp, e.hp + 400); // Extra for self
                            }
                        }
                        if (this.isPlayer) addKillMsg('💚 HEALING LAUGHTER!');
                        screenShake(6);
                        
                        // Custom healing effects: golden aura and beams
                        try {
                            effectsAdd(new AuraRing(this.x, this.y, 100, 3.0, '#FFD700', 8));
                            for (let i = 0; i < 10; i++) {
                                let angle = (Math.PI * 2 * i) / 10;
                                effectsAdd(new RadialBeam(this.x, this.y, angle, 120, Math.PI / 5, 3.0, '#32CD32'));
                            }
                        } catch(ex) {
                            console.warn('Heal effects failed', ex);
                        }
                        
                        // Enhanced healing particles
                        for (let i = 0; i < 30; i++) {
                            let angle = Math.random() * Math.PI * 2;
                            particles.push(new Particle(this.x, this.y, '#32CD32', 5, 1.4, Math.cos(angle) * 300, Math.sin(angle) * 300));
                        }
                        break;
                    case 'swap':
                        // Misfortune: Swap with closest enemy + 400 damage
                        let closest = null, minDist = 400;
                        for (let e of entities) {
                            if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if (d < minDist) {
                                    minDist = d;
                                    closest = e;
                                }
                            }
                        }
                        if (closest) {
                            closest.takeDamage(400, this);
                            let tempX = this.x, tempY = this.y;
                            this.x = closest.x; this.y = closest.y;
                            closest.x = tempX; closest.y = tempY;
                            if (this.isPlayer) addKillMsg('🔄 POSITIONS SWAPPED! (400 dmg)');
                            screenShake(8);
                            
                            // Custom swap effects: teleport flashes and trails
                            try {
                                effectsAdd(new ImpactFlash(tempX, tempY, this.angle, 50, 0.8, '#9932CC'));
                                effectsAdd(new ImpactFlash(this.x, this.y, this.angle + Math.PI, 50, 0.8, '#8B00FF'));
                                effectsAdd(new SwordTrail(tempX, tempY, this.angle, 400, 1.0, '#9932CC'));
                            } catch(ex) {
                                console.warn('Swap effects failed', ex);
                            }
                            
                            // Enhanced teleport particles
                            for (let i = 0; i < 25; i++) {
                                let angle = Math.random() * Math.PI * 2;
                                particles.push(new Particle(tempX, tempY, '#9932CC', 5, 1.2, Math.cos(angle) * 350, Math.sin(angle) * 350));
                                particles.push(new Particle(this.x, this.y, '#8B00FF', 5, 1.2, Math.cos(angle) * 350, Math.sin(angle) * 350));
                            }
                        }
                        break;
                    case 'clones':
                        // Clone Prank: 3 decoys (10s duration)
                        for (let i = 0; i < 3; i++) {
                            let angle = (Math.PI * 2 * i) / 3;
                            let decoyX = this.x + Math.cos(angle) * 100;
                            let decoyY = this.y + Math.sin(angle) * 100;
                            // Create temporary decoy entity
                            let decoy = new Entity(decoyX, decoyY, 20, this.color, 1);
                            decoy.team = this.team;
                            decoy.isDecoy = true;
                            entities.push(decoy);
                            setTimeout(() => {
                                if (decoy && !decoy.dead) {
                                    decoy.dead = true;
                                    entities.splice(entities.indexOf(decoy), 1);
                                }
                            }, 10000);
                        }
                        if (this.isPlayer) addKillMsg('👥 CLONES APPEAR!');
                        screenShake(7);
                        
                        // simple particle ring to indicate clones
                        for (let i = 0; i < 20; i++) {
                            let angle = Math.random() * Math.PI * 2;
                            particles.push(new Particle(this.x, this.y, '#FFD700', 4, 1.0, Math.cos(angle) * 200, Math.sin(angle) * 200));
                        }
                        break;
                }
                
                // Randomize the variant after using F
                this.currentFVariant = this.fVariants[Math.floor(Math.random() * this.fVariants.length)];
            }
            
            doReroll() {
                this.gCD = 10;
                
                // Start dash
                
                this.dashDist = 200;
                this.gDashDamaged = new Set();
                
                // Reroll F variant
                this.currentFVariant = this.fVariants[Math.floor(Math.random() * this.fVariants.length)];
                if (this.isPlayer) {
                    addKillMsg(`🎲 Rerolled to ${this.currentFVariant.emoji} ${this.currentFVariant.name}!`);
                    screenShake(4);
                }
                
                // Enhanced visual: Spinning dice wheel of fortune
                for (let i = 0; i < 30; i++) {
                    let angle = (Math.PI * 2 * i) / 30;
                    let radius = 40 + Math.sin(Date.now() / 100 + i) * 10;
                    particles.push(new Particle(
                        this.x + Math.cos(angle) * radius, 
                        this.y + Math.sin(angle) * radius, 
                        '#FFD700', 4, 1.0
                    ));
                }
                // Bright flash
                for (let i = 0; i < 15; i++) {
                    let angle = Math.random() * Math.PI * 2;
                    let speed = Math.random() * 250 + 150;
                    particles.push(new Particle(this.x, this.y, '#FFFFFF', 3, 0.8, Math.cos(angle) * speed, Math.sin(angle) * speed));
                }
            }
            
            
            useGear() {
                if (typeof Entity.prototype.useGear === 'function') {
                    return Entity.prototype.useGear.call(this);
                }
            }
            
            getEffectiveSpeed() {
                let spd = this.speed;
                if (this.speedsterTimer > 0) spd *= 1.5;
                if (this.rageTimer > 0) spd *= 1.1;
                return spd;
            }
            
            ai(dt, spd) {
                let target = this.findTarget();
                if (!target) {
                    this.wander(dt, spd);
                    return;
                }
                
                let dx = target.x - this.x;
                let dy = target.y - this.y;
                let dist = Math.sqrt(dx*dx + dy*dy);
                
                this.angle = Math.atan2(dy, dx);
                
                if (dist > 300) {
                    this.x += Math.cos(this.angle) * spd * dt;
                    this.y += Math.sin(this.angle) * spd * dt;
                }
                
                if (this.qCD <= 0 && dist < 550 && Math.random() < 0.1) this.doJestersToss();
                if (this.eCD <= 0 && dist < 250 && Math.random() < 0.15) this.doPrankstersPlay();
                if (this.fCD <= 0 && dist < 400 && Math.random() < 0.05) this.doGuess();
                if (this.gCD <= 0 && Math.random() < 0.08) this.doReroll();
                if (this.basicCD <= 0 && dist < 400 && Math.random() < 0.3) this.basicAtk();
            }
            
            findTarget() {
                let c = null, md = 9999;
                for (let e of entities) {
                    if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team && e.isVisibleTo(this)) {
                        let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                        if (d < md) { md = d; c = e; }
                    }
                }
                return c;
            }
            
            wander(dt, spd) {
                if (Math.random() < 0.02) {
                    this.angle = Math.random() * Math.PI * 2;
                }
                this.x += Math.cos(this.angle) * spd * dt * 0.5;
                this.y += Math.sin(this.angle) * spd * dt * 0.5;
            }
            
            draw(ctx) {
                super.draw(ctx);
                
                if (this.isPlayer) {
                    // Show current F variant
                    ctx.fillStyle = '#FFD700';
                    ctx.font = 'bold 16px Arial';
                    ctx.textAlign = 'center';
                    ctx.fillText(this.currentFVariant.emoji, this.x - camera.x, this.y - camera.y - 85);
                }
                
                // Draw banana peels
                for (let peel of this.bananaPeels) {
                    ctx.save();
                    let x = peel.x - camera.x;
                    let y = peel.y - camera.y;
                    // Simple circle with brown outline
                    ctx.fillStyle = '#FFFF00';
                    ctx.strokeStyle = '#8B4513';
                    ctx.lineWidth = 2;
                    ctx.beginPath();
                    ctx.arc(x, y, 15, 0, Math.PI * 2);
                    ctx.fill();
                    ctx.stroke();
                    ctx.restore();
                }
                
                
                // Draw custom projectiles for Jimeka (sharp darts)
                for (let proj of projectiles) {
                    if (proj.owner === this && proj.damage === 150) { // Basic attack
                        ctx.save();
                        ctx.translate(proj.x - camera.x, proj.y - camera.y);
                        ctx.rotate(proj.angle);
                        // Sharp dart shape
                        ctx.fillStyle = '#FF1493';
                        ctx.beginPath();
                        ctx.moveTo(0, 0);
                        ctx.lineTo(-5, -15); // Point
                        ctx.lineTo(0, -10);
                        ctx.lineTo(5, -15);
                        ctx.closePath();
                        ctx.fill();
                        // Metallic shine
                        ctx.strokeStyle = '#FFF';
                        ctx.lineWidth = 1;
                        ctx.beginPath();
                        ctx.moveTo(0, 0);
                        ctx.lineTo(0, -15);
                        ctx.stroke();
                        ctx.restore();
                    }
                }
            }
        }

        class Dayum extends Entity {
            constructor(x, y, p) {
                super(x, y, 30, '#000', 69420);
                this.isPlayer = p; this.countsAsFFAHero = true;
                this.name = p ? "Player (DAYUM)" : "Enemy DAYUM";
                this.basicCD = 0;
                this.qCD = 0;
                this.eCD = 0;
                this.fCD = 0;
                this.gCD = 0;
                this.baseSpd = 350;
                this.speed = 350;
                this.maxHp = 69420;
                this.hp = 69420;
                this.speedActive = false;
                this.speedTimer = 0;
            }

            update(dt) {
                if(this.dead) return;
                this.updateCommon(dt);
                if(this.basicCD > 0) this.basicCD -= dt;
                if(this.qCD > 0) this.qCD -= dt;
                if(this.eCD > 0) this.eCD -= dt;
                if(this.fCD > 0) this.fCD -= dt;
                if(this.gCD > 0) this.gCD -= dt;
                
                // Handle speed boost
                if(this.speedActive) {
                    this.speedTimer -= dt;
                    if(this.speedTimer <= 0) {
                        this.speedActive = false;
                        this.speed = this.baseSpd;
                    }
                }
                
                if(this.stunTimer > 0 || this.freezeTimer > 0) {
                    if(this.isPlayer) updateHUD(this);
                    return;
                }
                let spd = this.getEffectiveSpeed();
                if(this.isPlayer) {
                    this.input(dt, spd);
                    if(keys.r && this.rCD <= 0) this.useGear();
                    updateHUD(this);
                } else this.ai(dt, spd);
            }

            input(dt, spd) {
                let dx = 0, dy = 0;
                if(keys.w) dy--;
                if(keys.s) dy++;
                if(keys.a) dx--;
                if(keys.d) dx++;
                if(dx || dy) {
                    let m = new Vector2(dx, dy).norm().mult(spd * dt);
                    this.x += m.x;
                    this.y += m.y;
                }
                this.angle = getMouseAimAngle(this.x, this.y);
                if(mouse.down && this.basicCD <= 0) { this.fireAK47(); this.basicCD = 0.1; }
                if(keys.q && this.qCD <= 0) this.bombaclat();
                if(keys.e && this.eCD <= 0) this.fahhhhhh();
                if(keys.f && this.fCD <= 0) this.ultimateTrueDamage();
                if(keys.g && this.gCD <= 0) this.speedBoost();
            }

            fireAK47() {
                this.revealTimer = 0.3;
                for(let i = 0; i < 3; i++) {
                    entities.push(new Projectile(this, this.x, this.y, this.angle + (Math.random() - 0.5) * 0.3, 1000, 1000, 600, '#222'));
                }
            }

            bombaclat() {
                this.revealTimer = 0.6;
                let bomb = {
                    x: this.x,
                    y: this.y,
                    vx: Math.cos(this.angle) * 600,
                    vy: Math.sin(this.angle) * 600,
                    maxDist: 800,
                    dist: 0,
                    radius: 15,
                    owner: this,
                    shouldExplode: false,
                    update(dt) {
                        this.x += this.vx * dt;
                        this.y += this.vy * dt;
                        this.vy += 300 * dt; // gravity
                        this.dist = Math.sqrt((this.x - this.owner.x)**2 + (this.y - this.owner.y)**2);
                        
                        // Check if touching enemy in 200 radius
                        for(let e of entities) {
                            if(e !== this.owner && !e.dead && e instanceof Entity && e.team !== this.owner.team) {
                                let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                                if(d < 200) {
                                    this.shouldExplode = true;
                                    break;
                                }
                            }
                        }
                    },
                    draw(ctx, camX, camY) {
                        ctx.save();
                        ctx.translate(this.x - camX, this.y - camY);
                        
                        // Grenade body (dark gray/black sphere)
                        ctx.fillStyle = '#1a1a1a';
                        ctx.beginPath();
                        ctx.arc(0, 0, this.radius, 0, Math.PI * 2);
                        ctx.fill();
                        
                        // Grenade highlight
                        ctx.fillStyle = '#444';
                        ctx.beginPath();
                        ctx.arc(-this.radius/3, -this.radius/3, this.radius/3, 0, Math.PI * 2);
                        ctx.fill();
                        
                        // Fuse
                        ctx.strokeStyle = '#FFD700';
                        ctx.lineWidth = 2;
                        ctx.beginPath();
                        ctx.moveTo(0, -this.radius);
                        ctx.lineTo(Math.cos(performance.now() * 0.005) * 5, -this.radius - 8);
                        ctx.stroke();
                        
                        ctx.restore();
                    },
                    explode() {
                        for(let e of entities) {
                            if(e !== this.owner && !e.dead && e instanceof Entity && Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2) < 300) {
                                e.takeDamage(99999, this.owner);
                            }
                        }
                        for(let i = 0; i < 20; i++) {
                            particles.push(new Particle(this.x, this.y, '#FF0000', 5, 0.8));
                        }
                    }
                };
                window.dayumBombs = window.dayumBombs || [];
                window.dayumBombs.push(bomb);
                this.qCD = 5;
            }

            fahhhhhh() {
                this.revealTimer = 0.5;
                for(let e of entities) {
                    if(e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                        let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                        if(d < 300) {
                            e.takeDamage(500, this);
                            e.applyStatus('stun', 5, this);
                        }
                    }
                }
                for(let i = 0; i < 30; i++) {
                    particles.push(new Particle(this.x + Math.random() * 200 - 100, this.y + Math.random() * 200 - 100, '#0FF', 3, 0.6));
                }
                this.eCD = 5;
            }

            ultimateTrueDamage() {
                this.revealTimer = 1;
                screenShake(20);
                for(let e of entities) {
                    if(e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                        let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                        if(d < 1000) {
                            let trueDamage = this.maxHp;
                            e.takeDamage(trueDamage, this);
                        }
                    }
                }
                for(let i = 0; i < 50; i++) {
                    particles.push(new Particle(this.x + Math.random() * 400 - 200, this.y + Math.random() * 400 - 200, '#FFD700', 8, 1));
                }
                this.fCD = 10;
            }

            speedBoost() {
                this.speedActive = true;
                this.speedTimer = 3;
                this.speed = this.baseSpd * 10;
                for(let i = 0; i < 15; i++) {
                    particles.push(new Particle(this.x, this.y, '#FFA500', 2, 0.4));
                }
                this.gCD = 15;
            }

            ai(dt, spd) {
                if(this.handleSafeZone && this.handleSafeZone(dt)) return;
                let t = this.findTarget();
                if(!t) { this.wander(dt, spd); return; }
                let dx = t.x - this.x, dy = t.y - this.y;
                this.angle = Math.atan2(dy, dx);
                let d = Math.sqrt(dx*dx + dy*dy);
                if(d > 220) {
                    this.x += Math.cos(this.angle) * spd * dt;
                    this.y += Math.sin(this.angle) * spd * dt;
                }
                if(this.basicCD <= 0 && d < 220) this.fireAK47();
                if(this.qCD <= 0 && d < 650) this.bombaclat();
                if(this.eCD <= 0 && d < 340) this.fahhhhhh();
                if(this.fCD <= 0 && d < 700) this.ultimateTrueDamage();
                if(this.gCD <= 0 && this.hp < this.maxHp * 0.55) this.speedBoost();
            }

            findTarget() {
                let c = null, md = 9999;
                for(let e of entities) {
                    if(e !== this && !e.dead && e instanceof Entity && e.team !== this.team && e.isVisibleTo(this)) {
                        let d = Math.sqrt((e.x - this.x)**2 + (e.y - this.y)**2);
                        if(d < md) { md = d; c = e; }
                    }
                }
                return c;
            }

            wander(dt, spd) {
                if(Math.random() < 0.05) this.angle += (Math.random() - 0.5) * 1;
                this.x += Math.cos(this.angle) * spd * 0.5 * dt;
                this.y += Math.sin(this.angle) * spd * 0.5 * dt;
            }

            draw(ctx) {
                super.draw(ctx);
            }
        }

        // DEFENSE TOWER CLASS - 5v5 Mode
        class DefenseTower extends Entity {
            constructor(x, y, team, isMain) {
                super(x, y, 50, team === 1 ? '#4A90E2' : '#FF6B6B', 10000);
                this.team = team;
                this.isMain = isMain;
                this.isPlayer = false;
                this.name = team === 1 ? 'Blue Tower' : 'Red Tower';
                this.attackCD = 0;
                this.attackRange = 350;
                this.attackDamage = 200;
                this.speed = 0; // Towers don't move
                this.countsAsFFAHero = false;
            }
            
            update(dt) {
                if (this.dead) return;
                this.updateCommon(dt);
                if (this.attackCD > 0) this.attackCD -= dt;
                
                // Attack nearby enemies
                if (this.attackCD <= 0) {
                    for (let e of entities) {
                        if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                            let d = Math.sqrt((e.x - this.x) ** 2 + (e.y - this.y) ** 2);
                            if (d < this.attackRange) {
                                e.takeDamage(this.attackDamage, this);
                                this.attackCD = 2;
                                break;
                            }
                        }
                    }
                }
            }
            
            draw(ctx) {
                // Draw tower base (bigger)
                ctx.fillStyle = this.team === 1 ? '#4A90E2' : '#FF6B6B';
                ctx.beginPath();
                ctx.arc(this.x - camera.x, this.y - camera.y, 50, 0, Math.PI * 2);
                ctx.fill();
                
                // Draw tower top (antenna)
                ctx.fillStyle = this.team === 1 ? '#2E5C8A' : '#CC3333';
                ctx.fillRect(this.x - camera.x - 4, this.y - camera.y - 35, 8, 30);
                
                // Tower health bar (red background)
                ctx.fillStyle = '#3a0000';
                ctx.fillRect(this.x - camera.x - 25, this.y - camera.y - 60, 50, 4);
                
                // Tower health bar (green fill)
                ctx.fillStyle = '#0f0';
                ctx.fillRect(this.x - camera.x - 25, this.y - camera.y - 60, (this.hp / this.maxHp) * 50, 4);
            }
        }
        
        // MAIN TOWER CLASS - Final objective in 5v5
        class MainTower extends Entity {
            constructor(x, y, team) {
                super(x, y, 60, team === 1 ? '#00BFFF' : '#FF4444', 20000);
                this.team = team;
                this.isMain = true;
                this.isPlayer = false;
                this.name = team === 1 ? 'Blue Base' : 'Red Base';
                this.attackCD = 0;
                this.attackRange = 400;
                this.attackDamage = 250;
                this.speed = 0; // Towers don't move
                this.countsAsFFAHero = false;
            }
            
            update(dt) {
                if (this.dead) return;
                this.updateCommon(dt);
                if (this.attackCD > 0) this.attackCD -= dt;
                
                // Attack nearby enemies
                if (this.attackCD <= 0) {
                    for (let e of entities) {
                        if (e !== this && !e.dead && e instanceof Entity && e.team !== this.team) {
                            let d = Math.sqrt((e.x - this.x) ** 2 + (e.y - this.y) ** 2);
                            if (d < this.attackRange) {
                                e.takeDamage(this.attackDamage, this);
                                this.attackCD = 1.5;
                                break;
                            }
                        }
                    }
                }
            }
            
            draw(ctx) {
                // Draw main tower base (large circle)
                ctx.fillStyle = this.team === 1 ? '#00BFFF' : '#FF4444';
                ctx.beginPath();
                ctx.arc(this.x - camera.x, this.y - camera.y, 60, 0, Math.PI * 2);
                ctx.fill();
                
                // Draw tower core (brighter center)
                ctx.fillStyle = this.team === 1 ? '#00ffff' : '#ff6666';
                ctx.beginPath();
                ctx.arc(this.x - camera.x, this.y - camera.y, 40, 0, Math.PI * 2);
                ctx.fill();
                
                // Tower health bar (larger)
                ctx.fillStyle = '#3a0000';
                ctx.fillRect(this.x - camera.x - 50, this.y - camera.y - 70, 100, 5);
                ctx.fillStyle = '#0f0';
                ctx.fillRect(this.x - camera.x - 50, this.y - camera.y - 70, (this.hp / this.maxHp) * 100, 5);
                
                // HP text
                ctx.fillStyle = '#fff';
                ctx.font = 'bold 16px Arial';
                ctx.textAlign = 'center';
                ctx.fillText(Math.ceil(this.hp), this.x - camera.x, this.y - camera.y + 10);
            }
        }

