        // Handle selectGameMode for online FFA
        const originalSelectGameMode = window.selectGameMode;
        window.selectGameMode = function(mode) {
                    if (mode === 'ffa_online') {
                        initializeOnlineFFA();
                        gameMode = 'ffa_online';
                        document.getElementById('modeTitle').innerText = 'SELECT YOUR HERO (Online FFA)';
                    } else if (mode === '5v5_online') {
                        // Online 5v5 uses same socket system but requests 5v5 matchmaking
                        initializeOnline5v5();
                        gameMode = '5v5_online';
                        document.getElementById('modeTitle').innerText = 'SELECT YOUR HERO (Online 5v5)';
                    } else if (mode === 'duel_online') {
                        // 1v1 duel mode (online)
                        initializeOnlineFFA();
                        gameMode = 'duel_online';
                        document.getElementById('modeTitle').innerText = 'SELECT YOUR HERO (Online 1v1)';
                    } else if (mode === '1v1') {
                        // 1v1 offline mode (vs bot)
                        gameMode = '1v1';
                        document.getElementById('modeTitle').innerText = 'SELECT YOUR HERO (1v1 vs Bot)';
                    } else {
                        if (originalSelectGameMode) originalSelectGameMode(mode);
                    }
        };

        // Handle startGame for online FFA/duel
        const originalStartGame = window.startGame;
        window.startGame = function() {
                    if (gameMode === 'ffa_online') {
                        startOnlineFFA();
                    } else if (gameMode === '5v5_online') {
                        startOnline5v5();
                    } else if (gameMode === 'duel_online') {
                        startOnlineDuel();
                    } else if (gameMode === '1v1') {
                        start1v1();
                    } else {
                        if (originalStartGame) originalStartGame();
                    }
        };
    
    // Skin registry with icon image and sound properties
    const skinData = {};
    let selectedSkins = {}; // map of hero -> selected skin
    let currentSkinIcon = null; // reference to current icon during gameplay

    function registerSkins(hero, skinList) {
        skinData[hero] = skinList;
    }

    function openSkinMenu(heroName) {
        const skins = skinData[heroName] || [{name: 'default'}];
        const currentSkin = selectedSkins[heroName] || 'default';
        
        let modal = document.getElementById('skinSelectModal');
        if (!modal) {
            modal = document.createElement('div');
            modal.id = 'skinSelectModal';
            modal.setAttribute('data-modal-open', 'true');
            modal.style.cssText = 'position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:linear-gradient(135deg,#0f0f1e 0%,#1a1a2e 100%);border:4px solid #00ff88;padding:40px;border-radius:20px;z-index:2000;text-align:center;color:white;box-shadow:0 0 60px rgba(0,255,136,0.8), inset 0 0 40px rgba(0,255,136,0.2);font-family:Arial,sans-serif;max-height:85vh;overflow-y:auto;min-width:400px;';
            document.body.appendChild(modal);
        }
        
        let html = `<h2 style="color:#00ff88;margin-bottom:30px;text-shadow:0 0 15px #00ff88;font-size:28px;letter-spacing:2px;">${heroName.toUpperCase()} SKINS</h2>`;
        html += `<div style="display:grid;grid-template-columns:repeat(2,1fr);gap:20px;margin-bottom:30px;">`;
        
        skins.forEach(skin => {
            const skinName = skin.name || skin;
            const icon = skin.icon || '';
            const isSelected = skinName === currentSkin ? 'border:3px solid #00ff88;box-shadow:0 0 25px #00ff88,inset 0 0 15px rgba(0,255,136,0.3);transform:scale(1.05);' : 'border:2px solid #444;opacity:0.8;';
            const displayName = skinName === 'default' ? 'Default' : skinName.split('-').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
            
            html += `<div style="padding:15px;background:rgba(0,255,136,0.05);border-radius:12px;cursor:pointer;transition:all 0.3s ease;${isSelected}" onclick="selectSkin('${heroName}', '${skinName}')">`;
            if (icon) {
                html += `<img src="${icon}" style="width:100%;height:120px;object-fit:contain;border-radius:6px;margin-bottom:12px;background:rgba(0,0,0,0.3);" />`;
            } else {
                html += `<div style="width:100%;height:120px;background:rgba(0,255,136,0.1);border-radius:6px;margin-bottom:12px;display:flex;align-items:center;justify-content:center;color:#00ff88;">Default</div>`;
            }
            html += `<div style="font-weight:bold;color:#00ff88;font-size:16px;">${displayName}</div>`;
            html += `</div>`;
        });
        
        html += `</div>`;
        html += `<button onclick="closeSkinMenu()" style="background:linear-gradient(135deg,#ff3333,#ff6b6b);color:white;border:2px solid #ff3333;padding:12px 30px;border-radius:8px;cursor:pointer;font-weight:bold;font-size:16px;transition:all 0.3s;" onmouseover="this.style.boxShadow='0 0 20px rgba(255,51,51,0.8)'" onmouseout="this.style.boxShadow=''">Close</button>`;
        
        modal.innerHTML = html;
        modal.style.display = 'block';
    }
    
    function closeSkinMenu() {
        let modal = document.getElementById('skinSelectModal');
        if (modal) {
            modal.style.display = 'none';
            modal.removeAttribute('data-modal-open');
        }
    }

    function selectSkin(hero, skinName) {
        selectedSkins[hero] = skinName;
        console.log(`🎨 Selected skin: ${hero} -> ${skinName}`);
        // update the UI
        openSkinMenu(hero);
    }

    function getSkinIcon(hero, skinName) {
        const skins = skinData[hero] || [];
        const skin = skins.find(s => (s.name || s) === skinName);
        return skin && skin.icon ? skin.icon : null;
    }

    function ensureSkinImage(entity, hero, skinName) {
        const icon = getSkinIcon(hero, skinName);
        if (!icon) return null;
        entity.skinImageCache = entity.skinImageCache || {};
        const key = `${hero}:${skinName}`;
        const cached = entity.skinImageCache[key];
        if (cached && cached.src === icon) return cached;
        const img = new Image();
        img.decoding = 'async';
        img.crossOrigin = 'anonymous';
        img.onload = () => { img._loaded = true; };
        img.onerror = () => { img._loaded = false; };
        img.src = icon;
        entity.skinImageCache[key] = img;
        return img;
    }

    function drawSkinImage(ctx, entity, hero, skinName, borderColor, options = {}) {
        const icon = getSkinIcon(hero, skinName);
        if (!icon) return false;
        const img = ensureSkinImage(entity, hero, skinName);
        if (!img || !img.complete || !img.naturalWidth) return false;
        ctx.save();
        ctx.beginPath();
        ctx.arc(entity.x - camera.x, entity.y - camera.y, entity.radius, 0, Math.PI * 2);
        ctx.clip();
        ctx.filter = options.filter || 'brightness(0.92) saturate(0.9)';
        ctx.globalAlpha = options.alpha ?? 0.98;
        ctx.drawImage(
            img,
            entity.x - camera.x - entity.radius,
            entity.y - camera.y - entity.radius,
            entity.radius * 2,
            entity.radius * 2
        );
        ctx.restore();
        ctx.strokeStyle = borderColor || '#ffffff';
        ctx.lineWidth = options.lineWidth || 3;
        ctx.beginPath();
        ctx.arc(entity.x - camera.x, entity.y - camera.y, entity.radius, 0, Math.PI * 2);
        ctx.stroke();
        return true;
    }

    function getSkinSounds(hero, skinName) {
        const skins = skinData[hero] || [];
        const skin = skins.find(s => (s.name || s) === skinName);
        return skin && skin.sounds ? skin.sounds : {};
    }

